    /// Read one V2 animated socket link by its non-CAS lookup key.  Readback
    /// is fail-closed and never repairs reachability.
    pub fn get_game_weapon_animated_glb_socket_materialization_v2_link(
        &self,
        animated_socket_materialization_key_sha256: &str,
    ) -> Result<Option<GameWeaponAnimatedGlbSocketMaterializationV2LinkRecord>, StoreError> {
        if !is_sha256(animated_socket_materialization_key_sha256) {
            return Err(StoreError::InvalidData(
                "V2 animated GLB socket materialization key hash is invalid".to_owned(),
            ));
        }
        let connection = self.lock_connection()?;
        let link = connection
            .query_row(
                "SELECT payload_json FROM game_weapon_animated_glb_socket_materialization_v2_links WHERE animated_socket_materialization_key_sha256 = ?1",
                params![animated_socket_materialization_key_sha256],
                game_weapon_animated_glb_socket_materialization_v2_link_from_payload_row,
            )
            .optional()?;
        let Some(link) = link else {
            return Ok(None);
        };
        let value = game_weapon_animated_glb_socket_materialization_v2_value(&link)?;
        if game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "animated_socket_materialization_key_sha256",
        )? != animated_socket_materialization_key_sha256
        {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_KEY_BINDING_MISMATCH".to_owned(),
                message: "stored V2 animated socket row key differs from payload".to_owned(),
            });
        }
        validate_game_weapon_animated_glb_socket_materialization_v2_link(&link)?;
        validate_game_weapon_animated_glb_socket_materialization_v2_bindings_in_transaction(
            &connection,
            &link,
        )?;
        ensure_game_weapon_animated_glb_socket_materialization_v2_objects(&connection, &value)?;
        drop(connection);
        let receipt_hash = game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "receipt_object_sha256",
        )?;
        let receipt_bytes = self
            .cas
            .read_verified_bounded(receipt_hash, MAX_GAME_ASSET_DELIVERY_JSON_BYTES)
            .map_err(StoreError::Cas)?;
        validate_game_weapon_animated_glb_socket_materialization_v2_receipt_bytes(
            &receipt_bytes,
            &value,
        )?;
        let parent_key = game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "animation_glb_key_sha256",
        )?;
        let parent = self
            .get_mechanical_animation_glb_v2_link(parent_key)?
            .ok_or_else(|| StoreError::Contract {
                code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_PARENT_NOT_FOUND".to_owned(),
                message: "stored V2 animated socket parent is unavailable".to_owned(),
            })?;
        validate_game_weapon_animated_glb_socket_materialization_v2_source_bindings(
            self, &link, &parent,
        )?;
        for (field, max_bytes) in [
            ("appearance_artifact_sha256", 64 * 1024 * 1024),
            ("animated_artifact_sha256", 64 * 1024 * 1024),
            (
                "animation_receipt_object_sha256",
                MAX_GAME_ASSET_DELIVERY_JSON_BYTES,
            ),
            ("clip_object_sha256", MAX_MECHANICAL_ANIMATION_CLIP_V2_BYTES),
            (
                "anchor_set_object_sha256",
                MAX_GAME_ASSET_DELIVERY_JSON_BYTES,
            ),
            ("derived_animated_socket_artifact_sha256", 64 * 1024 * 1024),
        ] {
            self.cas
                .read_verified_bounded(
                    game_weapon_animated_glb_socket_materialization_v2_value_string(&value, field)?,
                    max_bytes,
                )
                .map_err(StoreError::Cas)?;
        }
        Ok(Some(link))
    }

