    pub fn record_fictional_energy_vfx_link(
        &self,
        link: &FictionalEnergyVfxLinkRecord,
    ) -> Result<FictionalEnergyVfxLinkRecord, StoreError> {
        validate_fictional_energy_vfx_link(link)?;
        let object = self
            .get_object(&link.vfx_profile_object_sha256)?
            .ok_or_else(|| StoreError::Contract {
                code: "FICTIONAL_ENERGY_VFX_OBJECT_INVALID".to_owned(),
                message: "VFX profile CAS metadata is unavailable".to_owned(),
            })?;
        if object.kind != FICTIONAL_ENERGY_VFX_PROFILE_KIND
            || object.mime != GAME_ASSET_DELIVERY_JSON_MIME
            || object.size_bytes == 0
            || object.size_bytes > MAX_GAME_ASSET_DELIVERY_JSON_BYTES
        {
            return Err(StoreError::Contract {
                code: "FICTIONAL_ENERGY_VFX_OBJECT_INVALID".to_owned(),
                message: "VFX profile CAS metadata is invalid".to_owned(),
            });
        }
        self.cas
            .read_verified_bounded(
                &link.vfx_profile_object_sha256,
                MAX_GAME_ASSET_DELIVERY_JSON_BYTES,
            )
            .map_err(StoreError::Cas)?;
        let mut connection = self.lock_connection()?;
        let transaction = connection.transaction()?;
        validate_fictional_energy_vfx_binding_in_transaction(&transaction, link)?;
        let existing = transaction
            .query_row(
                "SELECT project_id, delivery_manifest_object_sha256, anchor_set_object_sha256, material_pack_manifest_sha256, request_sha256, vfx_profile_object_sha256, materialization_status, canonical_sha256, created_at FROM fictional_energy_vfx_links WHERE delivery_manifest_object_sha256 = ?1",
                params![link.delivery_manifest_object_sha256],
                fictional_energy_vfx_link_from_row,
            )
            .optional()?;
        if let Some(existing) = existing {
            if !same_fictional_energy_vfx_link(&existing, link) {
                return Err(StoreError::Contract {
                    code: "FICTIONAL_ENERGY_VFX_LINK_CONFLICT".to_owned(),
                    message: "delivery is already bound to a different VFX profile".to_owned(),
                });
            }
            mark_reachable_in_transaction(
                &transaction,
                std::slice::from_ref(&existing.vfx_profile_object_sha256),
            )?;
            transaction.commit()?;
            return Ok(existing);
        }
        transaction.execute(
            "INSERT INTO fictional_energy_vfx_links (delivery_manifest_object_sha256, project_id, anchor_set_object_sha256, material_pack_manifest_sha256, request_sha256, vfx_profile_object_sha256, materialization_status, canonical_sha256, created_at) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)",
            params![link.delivery_manifest_object_sha256, link.project_id, link.anchor_set_object_sha256, link.material_pack_manifest_sha256, link.request_sha256, link.vfx_profile_object_sha256, link.materialization_status, link.canonical_sha256, link.created_at],
        )?;
        mark_reachable_in_transaction(
            &transaction,
            std::slice::from_ref(&link.vfx_profile_object_sha256),
        )?;
        transaction.commit()?;
        Ok(link.clone())
    }

