fn validate_mechanical_animation_glb_v2_link(
    link: &MechanicalAnimationGlbV2LinkRecord,
) -> Result<(), StoreError> {
    let mut canonical = link.clone();
    canonical.canonical_sha256.clear();
    let expected = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    let ids = [
        link.project_id.as_str(),
        link.appearance_candidate_id.as_str(),
        link.appearance_artifact_id.as_str(),
        link.source_geometry_candidate_id.as_str(),
        link.source_geometry_artifact_id.as_str(),
        link.material_surface_quality_id.as_str(),
        link.material_pack_id.as_str(),
        link.clip_id.as_str(),
    ];
    let hashes = [
        link.animation_glb_key_sha256.as_str(),
        link.appearance_candidate_state_sha256.as_str(),
        link.appearance_artifact_sha256.as_str(),
        link.appearance_artifact_readback_sha256.as_str(),
        link.appearance_artifact_readback_object_sha256.as_str(),
        link.source_geometry_candidate_state_sha256.as_str(),
        link.source_geometry_artifact_sha256.as_str(),
        link.source_geometry_candidate_evidence_sha256.as_str(),
        link.material_surface_quality_report_object_sha256.as_str(),
        link.material_surface_quality_canonical_sha256.as_str(),
        link.appearance_source_lineage_sidecar_object_sha256
            .as_str(),
        link.appearance_source_lineage_canonical_sha256.as_str(),
        link.appearance_program_object_sha256.as_str(),
        link.appearance_program_sha256.as_str(),
        link.geometry_program_object_sha256.as_str(),
        link.geometry_program_sha256.as_str(),
        link.geometry_preservation_projection_sha256.as_str(),
        link.operator_catalog_sha256.as_str(),
        link.readback_config_sha256.as_str(),
        link.material_pack_manifest_object_sha256.as_str(),
        link.material_pack_manifest_sha256.as_str(),
        link.material_pack_provenance_sha256.as_str(),
        link.texture_build_receipt_object_sha256.as_str(),
        link.texture_build_receipt_canonical_sha256.as_str(),
        link.candidate_surface_bake_receipt_object_sha256.as_str(),
        link.candidate_surface_bake_receipt_canonical_sha256
            .as_str(),
        link.clip_object_sha256.as_str(),
        link.clip_sha256.as_str(),
        link.rest_frame_sha256.as_str(),
        link.pose_action_sha256.as_str(),
        link.sampling_policy_sha256.as_str(),
        link.source_replay_worker_cohort_sha256.as_str(),
        link.animated_artifact_sha256.as_str(),
        link.animated_artifact_readback_sha256.as_str(),
        link.receipt_object_sha256.as_str(),
        link.receipt_canonical_sha256.as_str(),
        link.request_sha256.as_str(),
        link.canonical_sha256.as_str(),
    ];
    if link.schema_version != MECHANICAL_ANIMATION_GLB_V2_SCHEMA
        || ids.iter().any(|value| !is_opaque_id(value))
        || hashes.iter().any(|value| !is_sha256(value))
        || link.material_pack_version.is_empty()
        || link.material_pack_version.len() > 64
        || link.material_pack_license_spdx.is_empty()
        || link.material_pack_license_spdx.len() > 128
        || link.materialization_policy != MECHANICAL_ANIMATION_GLB_V2_POLICY
        || link.validator_status != MECHANICAL_ANIMATION_GLB_V2_VALIDATOR_STATUS
        || !link.hard_gate_passed
        || link.materialization_status != MECHANICAL_ANIMATION_GLB_V2_STATUS
        || !link.runtime_write_performed
        || link.production_stage_advanced
        || link.candidate_confirmed
        || link.version_created
        || link.export_performed
        || link.quality_status != "structural_only"
        || link.visual_quality_status != "NOT_PROVEN"
        || link.commercial_fps_quality_status != "NOT_PROVEN"
        || link.human_review_status != "NOT_RUN"
        || link.commercial_engine_status != "NOT_RUN"
        || link.canonical_sha256 != expected
        || link.created_at.is_empty()
        || link.created_at.len() > 128
    {
        return Err(StoreError::InvalidData(
            "appearance-aware MechanicalAnimationGlb@2 link is malformed".to_owned(),
        ));
    }
    Ok(())
}

