fn validate_mechanical_animation_glb_v2_receipt_bytes(
    bytes: &[u8],
    link: &MechanicalAnimationGlbV2LinkRecord,
) -> Result<MechanicalAnimationGlbV2ReceiptRecord, StoreError> {
    let receipt: MechanicalAnimationGlbV2ReceiptRecord =
        serde_json::from_slice(bytes).map_err(|error| StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_RECEIPT_INVALID".to_owned(),
            message: format!("V2 animated GLB receipt JSON is invalid: {error}"),
        })?;
    let mut canonical = receipt.clone();
    canonical.canonical_sha256.clear();
    let expected = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    if receipt.schema_version != MECHANICAL_ANIMATION_GLB_V2_RECEIPT_SCHEMA
        || receipt.canonical_sha256 != expected
        || receipt.canonical_sha256 != link.receipt_canonical_sha256
        || receipt.animated_artifact_sha256 != link.animated_artifact_sha256
        || receipt.animated_artifact_readback_sha256 != link.animated_artifact_readback_sha256
        || !is_sha256(&receipt.animation_validation_sha256)
        || receipt.source_static_projection_exact != true
        || receipt.binary_prefix_exact != true
        || receipt.appearance_material_projection_exact != true
        || receipt.material_pack_identity_exact != true
        || !receipt.hard_gate_passed
        || receipt.validator_status != MECHANICAL_ANIMATION_GLB_V2_VALIDATOR_STATUS
        || receipt.materialization_status != MECHANICAL_ANIMATION_GLB_V2_STATUS
        || !receipt.runtime_write_performed
        || receipt.production_stage_advanced
        || receipt.candidate_confirmed
        || receipt.version_created
        || receipt.export_performed
        || receipt.quality_status != "structural_only"
        || receipt.visual_quality_status != "NOT_PROVEN"
        || receipt.commercial_fps_quality_status != "NOT_PROVEN"
        || receipt.human_review_status != "NOT_RUN"
        || receipt.commercial_engine_status != "NOT_RUN"
        || receipt.limitations.is_empty()
        || receipt.limitations.len() > 16
        || receipt.sample_time_ticks.len() < 2
        || receipt.sample_time_ticks.len() > 16
        || receipt.timebase_hz != 1000
        || receipt.interpolation != "LINEAR"
        || !receipt.no_skinning
        || !receipt.no_morph_targets
        || !is_sha256(&receipt.frame_preview_hashes_sha256)
        || !is_sha256(&receipt.frame_preview_worker_cohort_sha256)
        || receipt.part_ids.is_empty()
        || receipt.part_ids.len() > 256
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_RECEIPT_BINDING_MISMATCH".to_owned(),
            message: "V2 animated GLB receipt status or output binding is invalid".to_owned(),
        });
    }
    let link_value =
        serde_json::to_value(link).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    let receipt_value = serde_json::to_value(&receipt)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    for field in glb_v2_receipt_binding_fields() {
        if link_value.get(*field) != receipt_value.get(*field) {
            return Err(StoreError::Contract {
                code: "MECHANICAL_ANIMATION_GLB_V2_RECEIPT_BINDING_MISMATCH".to_owned(),
                message: format!("V2 receipt field {field} differs from compact link"),
            });
        }
    }
    Ok(receipt)
}

fn mechanical_animation_glb_v2_reachable_hashes(
    link: &MechanicalAnimationGlbV2LinkRecord,
) -> Vec<String> {
    let mut hashes = vec![
        link.appearance_artifact_sha256.clone(),
        link.appearance_artifact_readback_object_sha256.clone(),
        link.source_geometry_artifact_sha256.clone(),
        link.material_surface_quality_report_object_sha256.clone(),
        link.appearance_source_lineage_sidecar_object_sha256.clone(),
        link.appearance_program_object_sha256.clone(),
        link.geometry_program_object_sha256.clone(),
        link.material_pack_manifest_object_sha256.clone(),
        link.texture_build_receipt_object_sha256.clone(),
        link.candidate_surface_bake_receipt_object_sha256.clone(),
        link.clip_object_sha256.clone(),
        link.animated_artifact_sha256.clone(),
        link.receipt_object_sha256.clone(),
    ];
    hashes.sort();
    hashes.dedup();
    hashes
}

fn glb_v2_compare_fields(
    left: &Value,
    right: &Value,
    fields: &[&str],
    code: &str,
) -> Result<(), StoreError> {
    for field in fields {
        if left.get(*field) != right.get(*field) {
            return Err(StoreError::Contract {
                code: code.to_owned(),
                message: format!("V2 animated GLB binding field {field} differs"),
            });
        }
    }
    Ok(())
}

fn ensure_mechanical_animation_glb_v2_source_object(
    store: &Store,
    sha256: &str,
    mime: &str,
    kinds: &[&str],
    max_bytes: u64,
    role: &str,
) -> Result<(), StoreError> {
    let object = store
        .get_object(sha256)?
        .ok_or_else(|| StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_SOURCE_OBJECT_UNAVAILABLE".to_owned(),
            message: format!("V2 {role} CAS object is unavailable"),
        })?;
    if object.mime != mime
        || !kinds.contains(&object.kind.as_str())
        || object.size_bytes == 0
        || object.size_bytes > max_bytes
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_SOURCE_OBJECT_INVALID".to_owned(),
            message: format!("V2 {role} CAS object metadata is invalid"),
        });
    }
    store
        .cas
        .read_verified_bounded(sha256, max_bytes)
        .map_err(StoreError::Cas)?;
    Ok(())
}

fn validate_mechanical_animation_glb_v2_source_bindings(
    store: &Store,
    link: &MechanicalAnimationGlbV2LinkRecord,
) -> Result<(), StoreError> {
    let clip = store
        .get_mechanical_animation_clip_v2_link(&link.appearance_candidate_id, &link.clip_id)?
        .ok_or_else(|| StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_CLIP_V2_NOT_FOUND".to_owned(),
            message: "V2 animated GLB requires an existing Clip@2 row".to_owned(),
        })?;
    let link_value =
        serde_json::to_value(link).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    let clip_value =
        serde_json::to_value(&clip).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    glb_v2_compare_fields(
        &link_value,
        &clip_value,
        &[
            "project_id",
            "appearance_candidate_id",
            "appearance_candidate_state_sha256",
            "appearance_artifact_id",
            "appearance_artifact_sha256",
            "appearance_artifact_readback_sha256",
            "appearance_artifact_readback_object_sha256",
            "source_geometry_candidate_id",
            "source_geometry_candidate_state_sha256",
            "source_geometry_artifact_id",
            "source_geometry_artifact_sha256",
            "source_geometry_candidate_evidence_sha256",
            "material_surface_quality_id",
            "material_surface_quality_report_object_sha256",
            "material_surface_quality_canonical_sha256",
            "appearance_source_lineage_sidecar_object_sha256",
            "appearance_source_lineage_canonical_sha256",
            "appearance_program_object_sha256",
            "appearance_program_sha256",
            "geometry_program_object_sha256",
            "geometry_program_sha256",
            "geometry_preservation_projection_sha256",
            "operator_catalog_sha256",
            "readback_config_sha256",
            "rest_frame_sha256",
            "pose_action_sha256",
            "source_replay_worker_cohort_sha256",
            "quality_status",
            "visual_quality_status",
            "commercial_fps_quality_status",
            "human_review_status",
            "commercial_engine_status",
            "runtime_write_performed",
            "production_stage_advanced",
            "candidate_confirmed",
            "version_created",
            "export_performed",
        ],
        "MECHANICAL_ANIMATION_GLB_V2_CLIP_BINDING_MISMATCH",
    )?;
    if link.clip_id != clip.clip_id
        || link.clip_object_sha256 != clip.clip_object_sha256
        || link.clip_sha256 != clip.clip_sha256
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_CLIP_BINDING_MISMATCH".to_owned(),
            message: "V2 animated GLB renamed animation Clip binding differs".to_owned(),
        });
    }
    let clip_bytes = store
        .cas
        .read_verified_bounded(
            &clip.clip_object_sha256,
            MAX_MECHANICAL_ANIMATION_CLIP_V2_BYTES,
        )
        .map_err(StoreError::Cas)?;
    let clip_record: MechanicalAnimationClipV2Record = serde_json::from_slice(&clip_bytes)
        .map_err(|error| StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_CLIP_BINDING_MISMATCH".to_owned(),
            message: format!("V2 Clip@2 JSON cannot be re-read: {error}"),
        })?;
    if clip_record.sampling_policy_sha256 != link.sampling_policy_sha256 {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_CLIP_BINDING_MISMATCH".to_owned(),
            message: "V2 animated GLB sampling policy differs from Clip@2".to_owned(),
        });
    }

    let quality = store
        .get_candidate_material_surface_quality(&link.material_surface_quality_id)?
        .ok_or_else(|| StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_MATERIAL_QUALITY_NOT_FOUND".to_owned(),
            message: "V2 animated GLB material-surface quality row is unavailable".to_owned(),
        })?;
    if quality.project_id != link.project_id
        || quality.source_candidate_id != link.source_geometry_candidate_id
        || quality.source_candidate_state_sha256 != link.source_geometry_candidate_state_sha256
        || quality.source_artifact_id != link.source_geometry_artifact_id
        || quality.source_artifact_sha256 != link.source_geometry_artifact_sha256
        || quality.source_geometry_candidate_evidence_sha256
            != link.source_geometry_candidate_evidence_sha256
        || quality.output_candidate_id != link.appearance_candidate_id
        || quality.output_candidate_state_sha256 != link.appearance_candidate_state_sha256
        || quality.output_artifact_id != link.appearance_artifact_id
        || quality.output_artifact_sha256 != link.appearance_artifact_sha256
        || quality.output_artifact_readback_sha256 != link.appearance_artifact_readback_sha256
        || quality.output_artifact_readback_object_sha256
            != link.appearance_artifact_readback_object_sha256
        || quality.appearance_source_lineage_sidecar_object_sha256
            != link.appearance_source_lineage_sidecar_object_sha256
        || quality.appearance_source_lineage_canonical_sha256
            != link.appearance_source_lineage_canonical_sha256
        || quality.appearance_program_object_sha256 != link.appearance_program_object_sha256
        || quality.appearance_program_sha256 != link.appearance_program_sha256
        || quality.source_geometry_program_sha256 != link.geometry_program_sha256
        || quality.geometry_preservation_projection_sha256
            != link.geometry_preservation_projection_sha256
        || quality.material_surface_quality_id != link.material_surface_quality_id
        || quality.material_pack_id != link.material_pack_id
        || quality.material_pack_version != link.material_pack_version
        || quality.material_pack_license_spdx != link.material_pack_license_spdx
        || quality.material_pack_manifest_object_sha256 != link.material_pack_manifest_object_sha256
        || quality.material_pack_manifest_sha256 != link.material_pack_manifest_sha256
        || quality.material_pack_provenance_sha256 != link.material_pack_provenance_sha256
        || quality.texture_build_receipt_object_sha256 != link.texture_build_receipt_object_sha256
        || quality.texture_build_receipt_canonical_sha256
            != link.texture_build_receipt_canonical_sha256
        || quality.candidate_surface_bake_receipt_object_sha256
            != link.candidate_surface_bake_receipt_object_sha256
        || quality.candidate_surface_bake_receipt_canonical_sha256
            != link.candidate_surface_bake_receipt_canonical_sha256
        || quality.canonical_sha256 != link.material_surface_quality_canonical_sha256
        || !quality.hard_gate_passed
        || quality.validator_status != "passed"
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_MATERIAL_QUALITY_BINDING_MISMATCH".to_owned(),
            message: "V2 animated GLB material quality does not bind exact Clip@2 source"
                .to_owned(),
        });
    }
    let lineage = store
        .get_appearance_source_lineage_link(
            &link.appearance_candidate_id,
            &link.appearance_program_sha256,
        )?
        .ok_or_else(|| StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_APPEARANCE_LINEAGE_NOT_FOUND".to_owned(),
            message: "V2 animated GLB AppearanceSourceLineage row is unavailable".to_owned(),
        })?;
    if lineage.project_id != link.project_id
        || lineage.candidate_id != link.appearance_candidate_id
        || lineage.candidate_state_sha256 != link.appearance_candidate_state_sha256
        || lineage.appearance_program_object_sha256 != link.appearance_program_object_sha256
        || lineage.appearance_program_sha256 != link.appearance_program_sha256
        || lineage.sidecar_object_sha256 != link.appearance_source_lineage_sidecar_object_sha256
        || lineage.canonical_sha256 != link.appearance_source_lineage_canonical_sha256
        || lineage.material_pack_id != link.material_pack_id
        || lineage.material_pack_version != link.material_pack_version
        || lineage.material_pack_license_spdx != link.material_pack_license_spdx
        || lineage.material_pack_provenance_sha256 != link.material_pack_provenance_sha256
        || lineage.material_pack_manifest_object_sha256 != link.material_pack_manifest_object_sha256
        || lineage.material_pack_manifest_sha256 != link.material_pack_manifest_sha256
        || lineage.texture_build_receipt_object_sha256 != link.texture_build_receipt_object_sha256
        || lineage.texture_build_receipt_sha256 != link.texture_build_receipt_canonical_sha256
        || lineage
            .candidate_surface_bake_receipt_object_sha256
            .as_deref()
            != Some(link.candidate_surface_bake_receipt_object_sha256.as_str())
        || lineage.candidate_surface_bake_receipt_sha256.as_deref()
            != Some(
                link.candidate_surface_bake_receipt_canonical_sha256
                    .as_str(),
            )
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_APPEARANCE_LINEAGE_BINDING_MISMATCH".to_owned(),
            message: "V2 animated GLB lineage/material pack binding differs".to_owned(),
        });
    }

    for (hash, mime, kinds, max, role) in [
        (
            &link.appearance_artifact_sha256,
            "model/gltf-binary",
            &["appearance-glb", "appearance-v2-glb"][..],
            64 * 1024 * 1024,
            "appearance artifact",
        ),
        (
            &link.appearance_artifact_readback_object_sha256,
            "application/json",
            &[
                "geometry-artifact-readback-v2",
                "appearance-v2-artifact-readback",
            ][..],
            MAX_MECHANICAL_ANIMATION_GLB_V2_RECEIPT_BYTES,
            "appearance readback",
        ),
        (
            &link.source_geometry_artifact_sha256,
            "model/gltf-binary",
            &["geometry-glb"][..],
            64 * 1024 * 1024,
            "source geometry artifact",
        ),
        (
            &link.material_surface_quality_report_object_sha256,
            "application/json",
            &[CANDIDATE_MATERIAL_SURFACE_QUALITY_REPORT_KIND][..],
            MAX_CANDIDATE_MATERIAL_SURFACE_QUALITY_REPORT_BYTES,
            "material quality report",
        ),
        (
            &link.appearance_source_lineage_sidecar_object_sha256,
            "application/json",
            &[APPEARANCE_SOURCE_LINEAGE_SIDECAR_KIND][..],
            MAX_APPEARANCE_SOURCE_JSON_BYTES,
            "AppearanceSourceLineage sidecar",
        ),
        (
            &link.appearance_program_object_sha256,
            "application/json",
            &[APPEARANCE_SOURCE_PROGRAM_KIND][..],
            MAX_APPEARANCE_SOURCE_JSON_BYTES,
            "Appearance program",
        ),
        (
            &link.geometry_program_object_sha256,
            "application/json",
            &[AUTHORING_MESH_EDIT_GEOMETRY_PROGRAM_KIND][..],
            MAX_APPEARANCE_SOURCE_JSON_BYTES,
            "geometry program",
        ),
        (
            &link.material_pack_manifest_object_sha256,
            "application/json",
            &[APPEARANCE_SOURCE_MATERIAL_PACK_KIND][..],
            MAX_APPEARANCE_SOURCE_JSON_BYTES,
            "material pack manifest",
        ),
        (
            &link.texture_build_receipt_object_sha256,
            "application/json",
            &[APPEARANCE_SOURCE_TEXTURE_RECEIPT_KIND][..],
            MAX_APPEARANCE_SOURCE_JSON_BYTES,
            "texture build receipt",
        ),
        (
            &link.candidate_surface_bake_receipt_object_sha256,
            "application/json",
            &["candidate-surface-bake-receipt"][..],
            MAX_APPEARANCE_SOURCE_JSON_BYTES,
            "surface bake receipt",
        ),
        (
            &link.clip_object_sha256,
            MECHANICAL_ANIMATION_CLIP_V2_MIME,
            &[MECHANICAL_ANIMATION_CLIP_V2_KIND][..],
            MAX_MECHANICAL_ANIMATION_CLIP_V2_BYTES,
            "Clip@2",
        ),
    ] {
        ensure_mechanical_animation_glb_v2_source_object(store, hash, mime, kinds, max, role)?;
    }
    Ok(())
}

fn validate_mechanical_animation_glb_v2_bindings_in_transaction(
    connection: &Connection,
    link: &MechanicalAnimationGlbV2LinkRecord,
) -> Result<(), StoreError> {
    let candidate: Option<(String, Option<String>, Option<String>, String)> = connection
        .query_row(
            "SELECT project_id, prepared_object_id, prepared_object_sha256, canonical_sha256 FROM candidates WHERE candidate_id = ?1",
            params![link.appearance_candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if candidate.as_ref().map(|row| row.0.as_str()) != Some(link.project_id.as_str())
        || candidate.as_ref().and_then(|row| row.1.as_deref())
            != Some(link.appearance_artifact_id.as_str())
        || candidate.as_ref().and_then(|row| row.2.as_deref())
            != Some(link.appearance_artifact_sha256.as_str())
        || candidate.as_ref().map(|row| row.3.as_str())
            != Some(link.appearance_candidate_state_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_APPEARANCE_CANDIDATE_FK_MISMATCH".to_owned(),
            message: "V2 animated GLB appearance candidate binding differs".to_owned(),
        });
    }
    let source: Option<(String, Option<String>, Option<String>, String)> = connection
        .query_row(
            "SELECT project_id, prepared_object_id, prepared_object_sha256, canonical_sha256 FROM candidates WHERE candidate_id = ?1",
            params![link.source_geometry_candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if source.as_ref().map(|row| row.0.as_str()) != Some(link.project_id.as_str())
        || source.as_ref().and_then(|row| row.1.as_deref())
            != Some(link.source_geometry_artifact_id.as_str())
        || source.as_ref().and_then(|row| row.2.as_deref())
            != Some(link.source_geometry_artifact_sha256.as_str())
        || source.as_ref().map(|row| row.3.as_str())
            != Some(link.source_geometry_candidate_state_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_SOURCE_GEOMETRY_FK_MISMATCH".to_owned(),
            message: "V2 animated GLB source geometry candidate binding differs".to_owned(),
        });
    }
    let clip: Option<MechanicalAnimationClipV2LinkRecord> = connection
        .query_row(
            "SELECT project_id, clip_id, appearance_candidate_id, appearance_candidate_state_sha256, appearance_artifact_id, appearance_artifact_sha256, appearance_artifact_readback_sha256, appearance_artifact_readback_object_sha256, source_geometry_candidate_id, source_geometry_candidate_state_sha256, source_geometry_artifact_id, source_geometry_artifact_sha256, source_geometry_candidate_evidence_sha256, material_surface_quality_id, material_surface_quality_report_object_sha256, material_surface_quality_canonical_sha256, appearance_source_lineage_sidecar_object_sha256, appearance_source_lineage_canonical_sha256, appearance_program_object_sha256, appearance_program_sha256, geometry_program_object_sha256, geometry_program_sha256, geometry_preservation_projection_sha256, operator_catalog_sha256, readback_config_sha256, clip_object_sha256, clip_sha256, rest_frame_sha256, pose_action_sha256, request_sha256, source_replay_worker_cohort_sha256, replay_policy, materialization_status, quality_status, visual_quality_status, commercial_fps_quality_status, human_review_status, commercial_engine_status, runtime_write_performed, production_stage_advanced, candidate_confirmed, version_created, export_performed, canonical_sha256, created_at FROM mechanical_animation_clip_v2_links WHERE appearance_candidate_id = ?1 AND clip_id = ?2",
            params![link.appearance_candidate_id, link.clip_id],
            mechanical_animation_clip_v2_link_from_row,
        )
        .optional()?;
    let Some(clip) = clip else {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_CLIP_FK_MISMATCH".to_owned(),
            message: "V2 animated GLB has no exact Clip@2 parent row".to_owned(),
        });
    };
    let link_value =
        serde_json::to_value(link).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    let clip_value =
        serde_json::to_value(&clip).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    glb_v2_compare_fields(
        &link_value,
        &clip_value,
        &[
            "project_id",
            "appearance_candidate_id",
            "appearance_candidate_state_sha256",
            "appearance_artifact_id",
            "appearance_artifact_sha256",
            "appearance_artifact_readback_sha256",
            "appearance_artifact_readback_object_sha256",
            "source_geometry_candidate_id",
            "source_geometry_candidate_state_sha256",
            "source_geometry_artifact_id",
            "source_geometry_artifact_sha256",
            "source_geometry_candidate_evidence_sha256",
            "material_surface_quality_id",
            "material_surface_quality_report_object_sha256",
            "material_surface_quality_canonical_sha256",
            "appearance_source_lineage_sidecar_object_sha256",
            "appearance_source_lineage_canonical_sha256",
            "appearance_program_object_sha256",
            "appearance_program_sha256",
            "geometry_program_object_sha256",
            "geometry_program_sha256",
            "geometry_preservation_projection_sha256",
            "operator_catalog_sha256",
            "readback_config_sha256",
            "rest_frame_sha256",
            "pose_action_sha256",
            "source_replay_worker_cohort_sha256",
            "quality_status",
            "visual_quality_status",
            "commercial_fps_quality_status",
            "human_review_status",
            "commercial_engine_status",
            "runtime_write_performed",
            "production_stage_advanced",
            "candidate_confirmed",
            "version_created",
            "export_performed",
        ],
        "MECHANICAL_ANIMATION_GLB_V2_CLIP_FK_MISMATCH",
    )?;
    if link.clip_id != clip.clip_id
        || link.clip_object_sha256 != clip.clip_object_sha256
        || link.clip_sha256 != clip.clip_sha256
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_CLIP_FK_MISMATCH".to_owned(),
            message: "V2 animated GLB renamed animation Clip FK differs".to_owned(),
        });
    }
    if connection
        .query_row(
            "SELECT 1 FROM objects WHERE sha256 = ?1",
            params![link.animation_glb_key_sha256],
            |_| Ok(()),
        )
        .optional()?
        .is_some()
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_GLB_V2_KEY_COLLIDES_WITH_CAS".to_owned(),
            message: "V2 animation key is a lookup identity, not a CAS object".to_owned(),
        });
    }
    for (hash, mime, role, max) in [
        (
            &link.appearance_artifact_sha256,
            "model/gltf-binary",
            "appearance artifact",
            64 * 1024 * 1024,
        ),
        (
            &link.appearance_artifact_readback_object_sha256,
            "application/json",
            "appearance readback",
            MAX_MECHANICAL_ANIMATION_GLB_V2_RECEIPT_BYTES,
        ),
        (
            &link.source_geometry_artifact_sha256,
            "model/gltf-binary",
            "source geometry artifact",
            64 * 1024 * 1024,
        ),
        (
            &link.material_surface_quality_report_object_sha256,
            "application/json",
            "material quality report",
            MAX_CANDIDATE_MATERIAL_SURFACE_QUALITY_REPORT_BYTES,
        ),
        (
            &link.appearance_source_lineage_sidecar_object_sha256,
            "application/json",
            "lineage sidecar",
            MAX_APPEARANCE_SOURCE_JSON_BYTES,
        ),
        (
            &link.appearance_program_object_sha256,
            "application/json",
            "appearance program",
            MAX_APPEARANCE_SOURCE_JSON_BYTES,
        ),
        (
            &link.geometry_program_object_sha256,
            "application/json",
            "geometry program",
            MAX_APPEARANCE_SOURCE_JSON_BYTES,
        ),
        (
            &link.material_pack_manifest_object_sha256,
            "application/json",
            "material pack manifest",
            MAX_APPEARANCE_SOURCE_JSON_BYTES,
        ),
        (
            &link.texture_build_receipt_object_sha256,
            "application/json",
            "texture build receipt",
            MAX_APPEARANCE_SOURCE_JSON_BYTES,
        ),
        (
            &link.candidate_surface_bake_receipt_object_sha256,
            "application/json",
            "surface bake receipt",
            MAX_APPEARANCE_SOURCE_JSON_BYTES,
        ),
        (
            &link.clip_object_sha256,
            MECHANICAL_ANIMATION_CLIP_V2_MIME,
            "Clip@2",
            MAX_MECHANICAL_ANIMATION_CLIP_V2_BYTES,
        ),
        (
            &link.animated_artifact_sha256,
            MECHANICAL_ANIMATION_GLB_V2_MIME,
            "animated GLB",
            MAX_MECHANICAL_ANIMATION_GLB_V2_BYTES,
        ),
        (
            &link.receipt_object_sha256,
            MECHANICAL_ANIMATION_GLB_V2_RECEIPT_MIME,
            "receipt",
            MAX_MECHANICAL_ANIMATION_GLB_V2_RECEIPT_BYTES,
        ),
    ] {
        let metadata: Option<(i64, String, String, String)> = connection
            .query_row(
                "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
                params![hash],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .optional()?;
        let Some((size_bytes, actual_mime, actual_kind, reachability)) = metadata else {
            return Err(StoreError::Contract {
                code: "MECHANICAL_ANIMATION_GLB_V2_OBJECT_FK_MISSING".to_owned(),
                message: format!("V2 {role} object is missing"),
            });
        };
        let expected_kinds: &[&str] = match role {
            "appearance artifact" => &["appearance-glb", "appearance-v2-glb"],
            "appearance readback" => &[
                "geometry-artifact-readback-v2",
                "appearance-v2-artifact-readback",
            ],
            "source geometry artifact" => &["geometry-glb"],
            "material quality report" => &[CANDIDATE_MATERIAL_SURFACE_QUALITY_REPORT_KIND],
            "lineage sidecar" => &[APPEARANCE_SOURCE_LINEAGE_SIDECAR_KIND],
            "appearance program" => &[APPEARANCE_SOURCE_PROGRAM_KIND],
            "geometry program" => &[AUTHORING_MESH_EDIT_GEOMETRY_PROGRAM_KIND],
            "material pack manifest" => &[APPEARANCE_SOURCE_MATERIAL_PACK_KIND],
            "texture build receipt" => &[APPEARANCE_SOURCE_TEXTURE_RECEIPT_KIND],
            "surface bake receipt" => &["candidate-surface-bake-receipt"],
            "Clip@2" => &[MECHANICAL_ANIMATION_CLIP_V2_KIND],
            "animated GLB" => &[MECHANICAL_ANIMATION_GLB_V2_KIND],
            "receipt" => &[MECHANICAL_ANIMATION_GLB_V2_RECEIPT_KIND],
            _ => &[],
        };
        if actual_mime != mime
            || !expected_kinds.contains(&actual_kind.as_str())
            || size_bytes <= 0
            || u64::try_from(size_bytes).unwrap_or(u64::MAX) > max
            || !matches!(reachability.as_str(), "temporary" | "reachable")
        {
            return Err(StoreError::Contract {
                code: "MECHANICAL_ANIMATION_GLB_V2_OBJECT_FK_INVALID".to_owned(),
                message: format!("V2 {role} object metadata is invalid"),
            });
        }
    }
    Ok(())
}

fn validate_mechanical_animation_clip_v2_link(
    link: &MechanicalAnimationClipV2LinkRecord,
) -> Result<(), StoreError> {
    let mut canonical = link.clone();
    canonical.canonical_sha256.clear();
    let expected = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    let ids = [
        link.project_id.as_str(),
        link.clip_id.as_str(),
        link.appearance_candidate_id.as_str(),
        link.appearance_artifact_id.as_str(),
        link.source_geometry_candidate_id.as_str(),
        link.source_geometry_artifact_id.as_str(),
        link.material_surface_quality_id.as_str(),
    ];
    let hashes = [
        link.appearance_candidate_state_sha256.as_str(),
        link.appearance_artifact_sha256.as_str(),
        link.appearance_artifact_readback_sha256.as_str(),
        link.appearance_artifact_readback_object_sha256.as_str(),
        link.source_geometry_candidate_state_sha256.as_str(),
        link.source_geometry_artifact_sha256.as_str(),
        link.source_geometry_candidate_evidence_sha256.as_str(),
        link.material_surface_quality_report_object_sha256.as_str(),
        link.material_surface_quality_canonical_sha256.as_str(),
        link.appearance_source_lineage_sidecar_object_sha256
            .as_str(),
        link.appearance_source_lineage_canonical_sha256.as_str(),
        link.appearance_program_object_sha256.as_str(),
        link.appearance_program_sha256.as_str(),
        link.geometry_program_object_sha256.as_str(),
        link.geometry_program_sha256.as_str(),
        link.geometry_preservation_projection_sha256.as_str(),
        link.operator_catalog_sha256.as_str(),
        link.readback_config_sha256.as_str(),
        link.clip_object_sha256.as_str(),
        link.clip_sha256.as_str(),
        link.rest_frame_sha256.as_str(),
        link.pose_action_sha256.as_str(),
        link.request_sha256.as_str(),
        link.source_replay_worker_cohort_sha256.as_str(),
        link.canonical_sha256.as_str(),
    ];
    if link.schema_version != "MechanicalAnimationClipLink@2"
        || ids.iter().any(|value| !is_opaque_id(value))
        || hashes.iter().any(|value| !is_sha256(value))
        || link.replay_policy != "geometry-plus-appearance-double-worker-replay@1"
        || link.materialization_status != "runtime-owned-immutable-cas-appearance-aware-clip"
        || link.quality_status != "structural_only"
        || link.visual_quality_status != "NOT_PROVEN"
        || link.commercial_fps_quality_status != "NOT_PROVEN"
        || link.human_review_status != "NOT_RUN"
        || link.commercial_engine_status != "NOT_RUN"
        || !link.runtime_write_performed
        || link.production_stage_advanced
        || link.candidate_confirmed
        || link.version_created
        || link.export_performed
        || link.canonical_sha256 != expected
        || link.created_at.is_empty()
        || link.created_at.len() > 128
    {
        return Err(StoreError::InvalidData(
            "appearance-aware MechanicalAnimationClip@2 link is malformed".to_owned(),
        ));
    }
    Ok(())
}

fn ensure_mechanical_animation_clip_v2_object(object: &CasObjectRecord) -> Result<(), StoreError> {
    if object.mime != MECHANICAL_ANIMATION_CLIP_V2_MIME
        || object.kind != MECHANICAL_ANIMATION_CLIP_V2_KIND
        || object.size_bytes == 0
        || object.size_bytes > MAX_MECHANICAL_ANIMATION_CLIP_V2_BYTES
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_OBJECT_INVALID".to_owned(),
            message: "V2 animation clip must be bounded canonical JSON".to_owned(),
        });
    }
    Ok(())
}

fn validate_mechanical_animation_clip_v2_clip_bytes(
    bytes: &[u8],
    link: &MechanicalAnimationClipV2LinkRecord,
) -> Result<(), StoreError> {
    let clip: MechanicalAnimationClipV2Record =
        serde_json::from_slice(bytes).map_err(|error| StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_INVALID".to_owned(),
            message: format!("V2 animation clip JSON is invalid: {error}"),
        })?;
    let mut canonical = clip.clone();
    canonical.canonical_sha256.clear();
    let expected = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    let embedded_canonical_hash = |value: &Value, expected: &str| -> bool {
        let Some(object) = value.as_object() else {
            return false;
        };
        let Some(actual) = object.get("canonical_sha256").and_then(Value::as_str) else {
            return false;
        };
        if actual != expected {
            return false;
        }
        let mut preimage = value.clone();
        preimage
            .as_object_mut()
            .expect("object checked above")
            .insert("canonical_sha256".to_owned(), Value::String(String::new()));
        canonical_json_hash(&preimage) == expected
    };
    let has_exact_keys = |value: &Value, expected: &[&str]| -> bool {
        let Some(object) = value.as_object() else {
            return false;
        };
        object.len() == expected.len() && expected.iter().all(|key| object.contains_key(*key))
    };
    let source_replay_ok = has_exact_keys(
        &clip.source_replay,
        &[
            "worker_build_cohort_sha256",
            "first_artifact_sha256",
            "repeat_artifact_sha256",
            "byte_exact_with_appearance_artifact",
            "appearance_materials_replayed",
            "strict_readback_passed",
        ],
    ) && clip
        .source_replay
        .get("worker_build_cohort_sha256")
        .and_then(Value::as_str)
        == Some(link.source_replay_worker_cohort_sha256.as_str())
        && clip
            .source_replay
            .get("first_artifact_sha256")
            .and_then(Value::as_str)
            == Some(link.appearance_artifact_sha256.as_str())
        && clip
            .source_replay
            .get("repeat_artifact_sha256")
            .and_then(Value::as_str)
            == Some(link.appearance_artifact_sha256.as_str())
        && clip
            .source_replay
            .get("byte_exact_with_appearance_artifact")
            .and_then(Value::as_bool)
            == Some(true)
        && clip
            .source_replay
            .get("appearance_materials_replayed")
            .and_then(Value::as_bool)
            == Some(true)
        && clip
            .source_replay
            .get("strict_readback_passed")
            .and_then(Value::as_bool)
            == Some(true);
    let sampling_policy_ok = has_exact_keys(
        &clip.sampling_policy,
        &[
            "schema_version",
            "timebase_hz",
            "interpolation",
            "unkeyed",
            "sample_time_ticks",
            "max_samples",
            "frame_preview_batch_size",
        ],
    ) && clip
        .sampling_policy
        .get("schema_version")
        .and_then(Value::as_str)
        == Some("MechanicalAnimationSamplingPolicy@1")
        && clip
            .sampling_policy
            .get("timebase_hz")
            .and_then(Value::as_u64)
            == Some(1000)
        && clip
            .sampling_policy
            .get("interpolation")
            .and_then(Value::as_str)
            == Some("scalar-linear-integer-ticks-clamped")
        && clip.sampling_policy.get("unkeyed").and_then(Value::as_str) == Some("rest")
        && clip
            .sampling_policy
            .get("max_samples")
            .and_then(Value::as_u64)
            == Some(16)
        && clip
            .sampling_policy
            .get("frame_preview_batch_size")
            .and_then(Value::as_u64)
            == Some(1)
        && clip
            .sampling_policy
            .get("sample_time_ticks")
            .and_then(Value::as_array)
            .is_some_and(|ticks| {
                !ticks.is_empty()
                    && ticks.len() <= 16
                    && ticks
                        .iter()
                        .all(|tick| tick.as_u64().is_some_and(|value| value <= 1_000_000))
                    && ticks
                        .iter()
                        .filter_map(Value::as_u64)
                        .collect::<HashSet<_>>()
                        .len()
                        == ticks.len()
            });
    let clip_value =
        serde_json::to_value(&clip).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    let link_matches = clip.schema_version == "MechanicalAnimationClip@2"
        && clip.clip_id == link.clip_id
        && clip.project_id == link.project_id
        && clip.appearance_candidate_id == link.appearance_candidate_id
        && clip.appearance_candidate_state_sha256 == link.appearance_candidate_state_sha256
        && clip.appearance_artifact_id == link.appearance_artifact_id
        && clip.appearance_artifact_sha256 == link.appearance_artifact_sha256
        && clip.appearance_artifact_readback_sha256 == link.appearance_artifact_readback_sha256
        && clip.appearance_artifact_readback_object_sha256
            == link.appearance_artifact_readback_object_sha256
        && clip.source_geometry_candidate_id == link.source_geometry_candidate_id
        && clip.source_geometry_candidate_state_sha256
            == link.source_geometry_candidate_state_sha256
        && clip.source_geometry_artifact_id == link.source_geometry_artifact_id
        && clip.source_geometry_artifact_sha256 == link.source_geometry_artifact_sha256
        && clip.source_geometry_candidate_evidence_sha256
            == link.source_geometry_candidate_evidence_sha256
        && clip.material_surface_quality_id == link.material_surface_quality_id
        && clip.material_surface_quality_report_object_sha256
            == link.material_surface_quality_report_object_sha256
        && clip.material_surface_quality_canonical_sha256
            == link.material_surface_quality_canonical_sha256
        && clip.appearance_source_lineage_sidecar_object_sha256
            == link.appearance_source_lineage_sidecar_object_sha256
        && clip.appearance_source_lineage_canonical_sha256
            == link.appearance_source_lineage_canonical_sha256
        && clip.appearance_program_object_sha256 == link.appearance_program_object_sha256
        && clip.appearance_program_sha256 == link.appearance_program_sha256
        && clip.geometry_program_object_sha256 == link.geometry_program_object_sha256
        && clip.geometry_program_sha256 == link.geometry_program_sha256
        && clip.geometry_preservation_projection_sha256
            == link.geometry_preservation_projection_sha256
        && clip.operator_catalog_sha256 == link.operator_catalog_sha256
        && clip.readback_config_sha256 == link.readback_config_sha256
        && clip.request_sha256 == link.request_sha256
        && clip.rest_frame_sha256 == link.rest_frame_sha256
        && clip.pose_action_sha256 == link.pose_action_sha256
        && clip.source_replay_worker_cohort_sha256 == link.source_replay_worker_cohort_sha256
        && clip.replay_policy == link.replay_policy
        && clip.materialization_status == link.materialization_status
        && clip.quality_status == link.quality_status
        && clip.visual_quality_status == link.visual_quality_status
        && clip.commercial_fps_quality_status == link.commercial_fps_quality_status
        && clip.human_review_status == link.human_review_status
        && clip.commercial_engine_status == link.commercial_engine_status
        && clip.runtime_write_performed == link.runtime_write_performed
        && clip.production_stage_advanced == link.production_stage_advanced
        && clip.candidate_confirmed == link.candidate_confirmed
        && clip.version_created == link.version_created
        && clip.export_performed == link.export_performed
        && clip.canonical_sha256 == link.clip_sha256
        && clip
            .sampling_policy
            .get("schema_version")
            .and_then(Value::as_str)
            == Some("MechanicalAnimationSamplingPolicy@1")
        && embedded_canonical_hash(&clip.rest_frame, &link.rest_frame_sha256)
        && embedded_canonical_hash(&clip.pose_action, &link.pose_action_sha256)
        && has_exact_keys(
            &clip.rest_frame,
            &[
                "schema_version",
                "rest_frame_id",
                "project_id",
                "artifact_id",
                "candidate_id",
                "program_sha256",
                "coordinate_system",
                "transform_convention",
                "root_link_id",
                "links",
                "parent_map",
                "evaluation_order",
                "parent_map_sha256",
                "canonical_sha256",
            ],
        )
        && has_exact_keys(
            &clip.pose_action,
            &[
                "schema_version",
                "action_id",
                "project_id",
                "candidate_id",
                "rest_frame_sha256",
                "program_sha256",
                "timebase_hz",
                "duration_ticks",
                "interpolation",
                "extrapolation",
                "unkeyed_policy",
                "channels",
                "canonical_sha256",
            ],
        )
        && sampling_policy_ok
        && canonical_json_hash(&clip.sampling_policy) == clip.sampling_policy_sha256
        && source_replay_ok
        && clip.canonical_sha256 == expected;
    if !link_matches || canonical_json_bytes(&clip_value).ok().as_deref() != Some(bytes) {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_BINDING_MISMATCH".to_owned(),
            message: "V2 animation clip bytes do not exactly bind the durable link".to_owned(),
        });
    }
    Ok(())
}

fn same_mechanical_animation_clip_v2_link(
    left: &MechanicalAnimationClipV2LinkRecord,
    right: &MechanicalAnimationClipV2LinkRecord,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left == right
}

