fn mechanical_animation_clip_v2_reachable_hashes(
    link: &MechanicalAnimationClipV2LinkRecord,
) -> Vec<String> {
    vec![link.clip_object_sha256.clone()]
}

fn validate_mechanical_animation_clip_v2_source_bindings(
    store: &Store,
    link: &MechanicalAnimationClipV2LinkRecord,
) -> Result<(), StoreError> {
    let appearance_candidate = store
        .get_candidate(&link.appearance_candidate_id)?
        .ok_or_else(|| StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_APPEARANCE_CANDIDATE_NOT_FOUND".to_owned(),
            message: "V2 appearance candidate is unavailable".to_owned(),
        })?;
    if appearance_candidate.project_id != link.project_id
        || appearance_candidate.canonical_sha256 != link.appearance_candidate_state_sha256
        || appearance_candidate.prepared_object_id.as_deref()
            != Some(link.appearance_artifact_id.as_str())
        || appearance_candidate.prepared_object_sha256.as_deref()
            != Some(link.appearance_artifact_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_APPEARANCE_CANDIDATE_BINDING_MISMATCH".to_owned(),
            message: "V2 appearance candidate/state/artifact binding differs".to_owned(),
        });
    }
    let source_candidate = store
        .get_candidate(&link.source_geometry_candidate_id)?
        .ok_or_else(|| StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_SOURCE_GEOMETRY_CANDIDATE_NOT_FOUND".to_owned(),
            message: "V2 source geometry candidate is unavailable".to_owned(),
        })?;
    if source_candidate.project_id != link.project_id
        || source_candidate.canonical_sha256 != link.source_geometry_candidate_state_sha256
        || source_candidate.prepared_object_id.as_deref()
            != Some(link.source_geometry_artifact_id.as_str())
        || source_candidate.prepared_object_sha256.as_deref()
            != Some(link.source_geometry_artifact_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_SOURCE_GEOMETRY_CANDIDATE_BINDING_MISMATCH"
                .to_owned(),
            message: "V2 source geometry candidate/state/artifact binding differs".to_owned(),
        });
    }
    let evidence = store
        .get_geometry_candidate_evidence(&link.source_geometry_candidate_id)?
        .ok_or_else(|| StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_SOURCE_GEOMETRY_EVIDENCE_NOT_FOUND".to_owned(),
            message: "V2 source geometry evidence is unavailable".to_owned(),
        })?;
    if evidence.project_id != link.project_id
        || evidence.candidate_id != link.source_geometry_candidate_id
        || evidence.artifact_object_sha256 != link.source_geometry_artifact_sha256
        || evidence.canonical_sha256 != link.source_geometry_candidate_evidence_sha256
        || evidence.geometry_program_object_sha256 != link.geometry_program_object_sha256
        || evidence.geometry_program_sha256 != link.geometry_program_sha256
        || evidence.operator_catalog_sha256 != link.operator_catalog_sha256
        || evidence.readback_config_sha256 != link.readback_config_sha256
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_SOURCE_GEOMETRY_EVIDENCE_BINDING_MISMATCH"
                .to_owned(),
            message: "V2 source geometry evidence/program/readback binding differs".to_owned(),
        });
    }

    let quality = store
        .get_candidate_material_surface_quality(&link.material_surface_quality_id)?
        .ok_or_else(|| StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_MATERIAL_QUALITY_NOT_FOUND".to_owned(),
            message: "V2 material-surface quality link is unavailable".to_owned(),
        })?;
    let quality_report_sha256: String = {
        let connection = store.lock_connection()?;
        connection.query_row(
            "SELECT report_object_sha256 FROM candidate_material_surface_quality_links WHERE material_surface_quality_id = ?1",
            params![link.material_surface_quality_id],
            |row| row.get(0),
        )?
    };
    if quality.project_id != link.project_id
        || quality.material_surface_quality_id != link.material_surface_quality_id
        || quality.source_candidate_id != link.source_geometry_candidate_id
        || quality.source_candidate_state_sha256 != link.source_geometry_candidate_state_sha256
        || quality.source_artifact_id != link.source_geometry_artifact_id
        || quality.source_artifact_sha256 != link.source_geometry_artifact_sha256
        || quality.source_geometry_candidate_evidence_sha256
            != link.source_geometry_candidate_evidence_sha256
        || quality.output_candidate_id != link.appearance_candidate_id
        || quality.output_candidate_state_sha256 != link.appearance_candidate_state_sha256
        || quality.output_artifact_id != link.appearance_artifact_id
        || quality.output_artifact_sha256 != link.appearance_artifact_sha256
        || quality.output_artifact_readback_sha256 != link.appearance_artifact_readback_sha256
        || quality.output_artifact_readback_object_sha256
            != link.appearance_artifact_readback_object_sha256
        || quality.appearance_source_lineage_sidecar_object_sha256
            != link.appearance_source_lineage_sidecar_object_sha256
        || quality.appearance_source_lineage_canonical_sha256
            != link.appearance_source_lineage_canonical_sha256
        || quality.appearance_program_object_sha256 != link.appearance_program_object_sha256
        || quality.appearance_program_sha256 != link.appearance_program_sha256
        || quality.source_geometry_program_sha256 != link.geometry_program_sha256
        || quality.geometry_preservation_projection_sha256
            != link.geometry_preservation_projection_sha256
        || quality.canonical_sha256 != link.material_surface_quality_canonical_sha256
        || quality_report_sha256 != link.material_surface_quality_report_object_sha256
        || !quality.hard_gate_passed
        || quality.validator_status != "passed"
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_MATERIAL_QUALITY_BINDING_MISMATCH".to_owned(),
            message: "V2 material-surface quality does not bind the exact source/output cohort"
                .to_owned(),
        });
    }
    let lineage = store
        .get_appearance_source_lineage_link(
            &link.appearance_candidate_id,
            &link.appearance_program_sha256,
        )?
        .ok_or_else(|| StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_APPEARANCE_LINEAGE_NOT_FOUND".to_owned(),
            message: "V2 AppearanceSourceLineage link is unavailable".to_owned(),
        })?;
    if lineage.project_id != link.project_id
        || lineage.candidate_id != link.appearance_candidate_id
        || lineage.candidate_state_sha256 != link.appearance_candidate_state_sha256
        || lineage.sidecar_object_sha256 != link.appearance_source_lineage_sidecar_object_sha256
        || lineage.canonical_sha256 != link.appearance_source_lineage_canonical_sha256
        || lineage.appearance_program_object_sha256 != link.appearance_program_object_sha256
        || lineage.appearance_program_sha256 != link.appearance_program_sha256
        || lineage.lod_candidate_ids.first().map(String::as_str)
            != Some(link.appearance_candidate_id.as_str())
        || lineage
            .lod_candidate_state_sha256s
            .first()
            .map(String::as_str)
            != Some(link.appearance_candidate_state_sha256.as_str())
        || lineage.lod_artifact_sha256s.first().map(String::as_str)
            != Some(link.appearance_artifact_sha256.as_str())
        || lineage
            .lod_artifact_readback_sha256s
            .first()
            .map(String::as_str)
            != Some(link.appearance_artifact_readback_sha256.as_str())
        || lineage
            .lod_artifact_readback_object_sha256s
            .first()
            .map(String::as_str)
            != Some(link.appearance_artifact_readback_object_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_APPEARANCE_LINEAGE_BINDING_MISMATCH".to_owned(),
            message: "V2 AppearanceSourceLineage does not bind the exact appearance artifact"
                .to_owned(),
        });
    }

    let ensure_object = |sha256: &str,
                         mime: &str,
                         kinds: &[&str],
                         max_bytes: u64,
                         role: &str|
     -> Result<(), StoreError> {
        let object = store
            .get_object(sha256)?
            .ok_or_else(|| StoreError::Contract {
                code: "MECHANICAL_ANIMATION_CLIP_V2_SOURCE_OBJECT_NOT_FOUND".to_owned(),
                message: format!("V2 {role} CAS object is unavailable"),
            })?;
        if object.mime != mime
            || !kinds.contains(&object.kind.as_str())
            || object.size_bytes == 0
            || object.size_bytes > max_bytes
        {
            return Err(StoreError::Contract {
                code: "MECHANICAL_ANIMATION_CLIP_V2_SOURCE_OBJECT_INVALID".to_owned(),
                message: format!("V2 {role} CAS object metadata is invalid"),
            });
        }
        store
            .cas
            .read_verified_bounded(sha256, max_bytes)
            .map_err(StoreError::Cas)?;
        Ok(())
    };
    ensure_object(
        &link.appearance_artifact_sha256,
        "model/gltf-binary",
        &["appearance-glb", "appearance-v2-glb"],
        64 * 1024 * 1024,
        "appearance artifact",
    )?;
    ensure_object(
        &link.source_geometry_artifact_sha256,
        "model/gltf-binary",
        &["geometry-glb"],
        64 * 1024 * 1024,
        "source geometry artifact",
    )?;
    ensure_object(
        &link.appearance_artifact_readback_object_sha256,
        "application/json",
        &[
            "geometry-artifact-readback-v2",
            "appearance-v2-artifact-readback",
        ],
        MAX_MECHANICAL_ANIMATION_CLIP_V2_BYTES,
        "appearance ArtifactReadback",
    )?;
    ensure_object(
        &link.appearance_source_lineage_sidecar_object_sha256,
        "application/json",
        &[APPEARANCE_SOURCE_LINEAGE_SIDECAR_KIND],
        MAX_APPEARANCE_SOURCE_JSON_BYTES,
        "AppearanceSourceLineage sidecar",
    )?;
    ensure_object(
        &link.appearance_program_object_sha256,
        "application/json",
        &[APPEARANCE_SOURCE_PROGRAM_KIND],
        MAX_APPEARANCE_SOURCE_JSON_BYTES,
        "Appearance program",
    )?;
    ensure_object(
        &link.geometry_program_object_sha256,
        "application/json",
        &[AUTHORING_MESH_EDIT_GEOMETRY_PROGRAM_KIND],
        MAX_APPEARANCE_SOURCE_JSON_BYTES,
        "geometry program",
    )?;
    ensure_object(
        &link.material_surface_quality_report_object_sha256,
        "application/json",
        &[CANDIDATE_MATERIAL_SURFACE_QUALITY_REPORT_KIND],
        MAX_CANDIDATE_MATERIAL_SURFACE_QUALITY_REPORT_BYTES,
        "material-surface quality report",
    )?;
    Ok(())
}

fn validate_mechanical_animation_clip_v2_bindings_in_transaction(
    connection: &Connection,
    link: &MechanicalAnimationClipV2LinkRecord,
) -> Result<(), StoreError> {
    let candidate: Option<(String, Option<String>, Option<String>, String)> = connection
        .query_row(
            "SELECT project_id, prepared_object_id, prepared_object_sha256, canonical_sha256 FROM candidates WHERE candidate_id = ?1",
            params![link.appearance_candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if candidate.as_ref().map(|row| row.0.as_str()) != Some(link.project_id.as_str())
        || candidate.as_ref().and_then(|row| row.1.as_deref())
            != Some(link.appearance_artifact_id.as_str())
        || candidate.as_ref().and_then(|row| row.2.as_deref())
            != Some(link.appearance_artifact_sha256.as_str())
        || candidate.as_ref().map(|row| row.3.as_str())
            != Some(link.appearance_candidate_state_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_APPEARANCE_CANDIDATE_FK_MISMATCH".to_owned(),
            message: "V2 appearance candidate FK/state/artifact binding differs".to_owned(),
        });
    }
    let source: Option<(String, Option<String>, Option<String>, String)> = connection
        .query_row(
            "SELECT project_id, prepared_object_id, prepared_object_sha256, canonical_sha256 FROM candidates WHERE candidate_id = ?1",
            params![link.source_geometry_candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if source.as_ref().map(|row| row.0.as_str()) != Some(link.project_id.as_str())
        || source.as_ref().and_then(|row| row.1.as_deref())
            != Some(link.source_geometry_artifact_id.as_str())
        || source.as_ref().and_then(|row| row.2.as_deref())
            != Some(link.source_geometry_artifact_sha256.as_str())
        || source.as_ref().map(|row| row.3.as_str())
            != Some(link.source_geometry_candidate_state_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_SOURCE_GEOMETRY_CANDIDATE_FK_MISMATCH".to_owned(),
            message: "V2 source geometry candidate FK/state/artifact binding differs".to_owned(),
        });
    }
    let evidence: Option<(String, String, String, String, String, String)> = connection
        .query_row(
            "SELECT project_id, artifact_object_sha256, canonical_sha256, geometry_program_object_sha256, geometry_program_sha256, readback_config_sha256 FROM geometry_candidate_evidence WHERE candidate_id = ?1",
            params![link.source_geometry_candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?)),
        )
        .optional()?;
    if evidence.as_ref().is_none_or(|row| {
        row.0 != link.project_id
            || row.1 != link.source_geometry_artifact_sha256
            || row.2 != link.source_geometry_candidate_evidence_sha256
            || row.3 != link.geometry_program_object_sha256
            || row.4 != link.geometry_program_sha256
            || row.5 != link.readback_config_sha256
    }) {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_SOURCE_GEOMETRY_EVIDENCE_FK_MISMATCH".to_owned(),
            message: "V2 source geometry evidence FK binding differs".to_owned(),
        });
    }
    let quality: Option<(String, String, String, String)> = connection
        .query_row(
            "SELECT project_id, output_candidate_id, output_artifact_sha256, report_object_sha256 FROM candidate_material_surface_quality_links WHERE material_surface_quality_id = ?1",
            params![link.material_surface_quality_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if quality.as_ref().is_none_or(|row| {
        row.0 != link.project_id
            || row.1 != link.appearance_candidate_id
            || row.2 != link.appearance_artifact_sha256
            || row.3 != link.material_surface_quality_report_object_sha256
    }) {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_MATERIAL_QUALITY_FK_MISMATCH".to_owned(),
            message: "V2 material-surface quality FK binding differs".to_owned(),
        });
    }
    let lineage = read_appearance_source_lineage_for_connection(
        connection,
        &link.appearance_candidate_id,
        &link.appearance_program_sha256,
    )?
    .ok_or_else(|| StoreError::Contract {
        code: "MECHANICAL_ANIMATION_CLIP_V2_APPEARANCE_LINEAGE_FK_MISMATCH".to_owned(),
        message: "V2 AppearanceSourceLineage FK binding is unavailable".to_owned(),
    })?;
    if lineage.project_id != link.project_id
        || lineage.sidecar_object_sha256 != link.appearance_source_lineage_sidecar_object_sha256
        || lineage.canonical_sha256 != link.appearance_source_lineage_canonical_sha256
    {
        return Err(StoreError::Contract {
            code: "MECHANICAL_ANIMATION_CLIP_V2_APPEARANCE_LINEAGE_FK_MISMATCH".to_owned(),
            message: "V2 AppearanceSourceLineage FK binding differs".to_owned(),
        });
    }
    for (hash, role) in [
        (&link.appearance_artifact_sha256, "appearance artifact"),
        (
            &link.appearance_artifact_readback_object_sha256,
            "appearance readback",
        ),
        (
            &link.source_geometry_artifact_sha256,
            "source geometry artifact",
        ),
        (
            &link.material_surface_quality_report_object_sha256,
            "material quality report",
        ),
        (
            &link.appearance_source_lineage_sidecar_object_sha256,
            "AppearanceSourceLineage sidecar",
        ),
        (&link.appearance_program_object_sha256, "appearance program"),
        (&link.geometry_program_object_sha256, "geometry program"),
        (&link.clip_object_sha256, "V2 animation clip"),
    ] {
        let object: Option<(i64, String, String, String)> = connection
            .query_row(
                "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
                params![hash],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .optional()?;
        if object.is_none() {
            return Err(StoreError::Contract {
                code: "MECHANICAL_ANIMATION_CLIP_V2_OBJECT_FK_MISSING".to_owned(),
                message: format!("V2 {role} object is missing"),
            });
        }
    }
    Ok(())
}

fn validate_game_asset_delivery_link(link: &GameAssetDeliveryLinkRecord) -> Result<(), StoreError> {
    let mut canonical = link.clone();
    canonical.canonical_sha256.clear();
    let expected_canonical = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    if link.schema_version != "GameAssetDeliveryLink@1"
        || !is_opaque_id(&link.project_id)
        || link.lod_candidate_ids.len() != 3
        || link
            .lod_candidate_ids
            .iter()
            .any(|value| !is_opaque_id(value))
        || link.lod_candidate_ids.iter().collect::<HashSet<_>>().len() != 3
        || link.lod_artifact_sha256s.len() != 3
        || link
            .lod_artifact_sha256s
            .iter()
            .any(|value| !is_sha256(value))
        || link
            .lod_artifact_sha256s
            .iter()
            .collect::<HashSet<_>>()
            .len()
            != 3
        || !is_sha256(&link.request_sha256)
        || !is_sha256(&link.lod_receipt_object_sha256)
        || !is_sha256(&link.collision_proxy_object_sha256)
        || !is_sha256(&link.readiness_object_sha256)
        || !is_sha256(&link.delivery_manifest_object_sha256)
        || link
            .animation_artifact_sha256
            .as_deref()
            .is_some_and(|value| !is_sha256(value))
        || link.materialization_status != "runtime-owned-durable-game-delivery-link"
        || link.canonical_sha256 != expected_canonical
        || link.created_at.is_empty()
        || link.created_at.len() > 128
    {
        return Err(StoreError::InvalidData(
            "game asset delivery link is malformed".to_owned(),
        ));
    }
    Ok(())
}

fn game_asset_delivery_link_from_row(
    row: &rusqlite::Row<'_>,
) -> rusqlite::Result<GameAssetDeliveryLinkRecord> {
    Ok(GameAssetDeliveryLinkRecord {
        schema_version: "GameAssetDeliveryLink@1".to_owned(),
        project_id: row.get(0)?,
        lod_candidate_ids: vec![row.get(1)?, row.get(2)?, row.get(3)?],
        lod_artifact_sha256s: vec![row.get(4)?, row.get(5)?, row.get(6)?],
        request_sha256: row.get(7)?,
        lod_receipt_object_sha256: row.get(8)?,
        collision_proxy_object_sha256: row.get(9)?,
        readiness_object_sha256: row.get(10)?,
        delivery_manifest_object_sha256: row.get(11)?,
        animation_artifact_sha256: row.get(12)?,
        materialization_status: row.get(13)?,
        canonical_sha256: row.get(14)?,
        created_at: row.get(15)?,
    })
}

fn same_game_asset_delivery_link(
    left: &GameAssetDeliveryLinkRecord,
    right: &GameAssetDeliveryLinkRecord,
) -> bool {
    left.schema_version == right.schema_version
        && left.project_id == right.project_id
        && left.lod_candidate_ids == right.lod_candidate_ids
        && left.lod_artifact_sha256s == right.lod_artifact_sha256s
        && left.request_sha256 == right.request_sha256
        && left.lod_receipt_object_sha256 == right.lod_receipt_object_sha256
        && left.collision_proxy_object_sha256 == right.collision_proxy_object_sha256
        && left.readiness_object_sha256 == right.readiness_object_sha256
        && left.delivery_manifest_object_sha256 == right.delivery_manifest_object_sha256
        && left.animation_artifact_sha256 == right.animation_artifact_sha256
        && left.materialization_status == right.materialization_status
        && left.canonical_sha256 == right.canonical_sha256
}

