fn validate_game_weapon_animated_glb_socket_materialization_link(
    link: &GameWeaponAnimatedGlbSocketMaterializationLinkRecord,
) -> Result<(), StoreError> {
    let mut canonical = link.clone();
    canonical.canonical_sha256.clear();
    let expected_canonical = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    if link.schema_version != "GameWeaponAnimatedGlbSocketMaterializationLink@1"
        || !is_sha256(&link.animated_socket_materialization_key_sha256)
        || !is_opaque_id(&link.project_id)
        || !is_opaque_id(&link.candidate_id)
        || !is_sha256(&link.candidate_state_sha256)
        || !is_sha256(&link.delivery_manifest_object_sha256)
        || !is_sha256(&link.lod0_artifact_sha256)
        || !is_sha256(&link.source_artifact_sha256)
        || !is_sha256(&link.source_artifact_readback_sha256)
        || !is_sha256(&link.animated_artifact_sha256)
        || !is_sha256(&link.animated_artifact_readback_sha256)
        || !is_sha256(&link.animation_receipt_object_sha256)
        || !is_sha256(&link.animation_receipt_canonical_sha256)
        || !is_sha256(&link.anchor_set_object_sha256)
        || !is_sha256(&link.anchor_set_canonical_sha256)
        || !is_sha256(&link.request_sha256)
        || link.socket_materialization_policy
            != GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_POLICY
        || link.lod_scope != GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_LOD_SCOPE
        || !is_sha256(&link.socket_node_id_encoding_sha256)
        || !is_sha256(&link.derived_animated_socket_artifact_sha256)
        || !is_sha256(&link.derived_animated_socket_artifact_readback_sha256)
        || !is_sha256(&link.receipt_object_sha256)
        || link.materialization_status != GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_STATUS
        || link.lod0_artifact_sha256 != link.source_artifact_sha256
        || link.canonical_sha256 != expected_canonical
        || link.created_at.is_empty()
        || link.created_at.len() > 128
    {
        return Err(StoreError::InvalidData(
            "game weapon animated GLB socket materialization link is malformed".to_owned(),
        ));
    }
    Ok(())
}

