fn validate_game_weapon_animated_glb_socket_materialization_v2_bindings_in_transaction(
    connection: &Connection,
    link: &GameWeaponAnimatedGlbSocketMaterializationV2LinkRecord,
) -> Result<(), StoreError> {
    let value = game_weapon_animated_glb_socket_materialization_v2_value(link)?;
    let child_key = game_weapon_animated_glb_socket_materialization_v2_value_string(
        &value,
        "animated_socket_materialization_key_sha256",
    )?;
    let parent_key = game_weapon_animated_glb_socket_materialization_v2_value_string(
        &value,
        "animation_glb_key_sha256",
    )?;
    let child_is_object: Option<i64> = connection
        .query_row(
            "SELECT 1 FROM objects WHERE sha256 = ?1",
            params![child_key],
            |row| row.get(0),
        )
        .optional()?;
    if child_is_object.is_some() {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_KEY_IS_CAS".to_owned(),
            message: "V2 animated socket parent key must remain a non-CAS lookup key".to_owned(),
        });
    }
    let parent_is_object: Option<i64> = connection
        .query_row(
            "SELECT 1 FROM objects WHERE sha256 = ?1",
            params![parent_key],
            |row| row.get(0),
        )
        .optional()?;
    if parent_is_object.is_some() {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_PARENT_KEY_IS_CAS".to_owned(),
            message: "MechanicalAnimationGlb@2 parent key must remain non-CAS".to_owned(),
        });
    }

    let parent: MechanicalAnimationGlbV2LinkRecord = connection
        .query_row(
            "SELECT payload_json FROM mechanical_animation_glb_v2_links WHERE animation_glb_key_sha256 = ?1",
            params![parent_key],
            mechanical_animation_glb_v2_link_from_payload_row,
        )
        .optional()?
        .ok_or_else(|| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_PARENT_FK_MISMATCH".to_owned(),
            message: "V2 animated socket has no MechanicalAnimationGlb@2 parent".to_owned(),
        })?;
    validate_mechanical_animation_glb_v2_link(&parent)?;
    let parent_value = serde_json::to_value(&parent)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    for (child_field, parent_field) in [
        ("project_id", "project_id"),
        ("appearance_candidate_id", "appearance_candidate_id"),
        (
            "appearance_candidate_state_sha256",
            "appearance_candidate_state_sha256",
        ),
        ("appearance_artifact_sha256", "appearance_artifact_sha256"),
        (
            "appearance_artifact_readback_sha256",
            "appearance_artifact_readback_sha256",
        ),
        ("animation_glb_key_sha256", "animation_glb_key_sha256"),
        ("animated_artifact_sha256", "animated_artifact_sha256"),
        (
            "animated_artifact_readback_sha256",
            "animated_artifact_readback_sha256",
        ),
        ("animation_receipt_object_sha256", "receipt_object_sha256"),
        (
            "animation_receipt_canonical_sha256",
            "receipt_canonical_sha256",
        ),
        ("clip_id", "clip_id"),
        ("clip_object_sha256", "clip_object_sha256"),
        ("clip_sha256", "clip_sha256"),
    ] {
        if value.get(child_field) != parent_value.get(parent_field) {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_PARENT_BINDING_MISMATCH".to_owned(),
                message: format!("V2 animated socket field {child_field} differs from parent"),
            });
        }
    }

    let appearance_candidate: Option<(String, Option<String>, String)> =
        connection
            .query_row(
                "SELECT project_id, prepared_object_sha256, canonical_sha256 FROM candidates WHERE candidate_id = ?1",
                params![game_weapon_animated_glb_socket_materialization_v2_value_string(
                    &value,
                    "appearance_candidate_id",
                )?],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .optional()?;
    if appearance_candidate.as_ref().map(|row| row.0.as_str())
        != Some(
            game_weapon_animated_glb_socket_materialization_v2_value_string(&value, "project_id")?,
        )
        || appearance_candidate.as_ref().map(|row| row.1.as_deref())
            != Some(Some(
                game_weapon_animated_glb_socket_materialization_v2_value_string(
                    &value,
                    "appearance_artifact_sha256",
                )?,
            ))
        || appearance_candidate.as_ref().map(|row| row.2.as_str())
            != Some(
                game_weapon_animated_glb_socket_materialization_v2_value_string(
                    &value,
                    "appearance_candidate_state_sha256",
                )?,
            )
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_APPEARANCE_CANDIDATE_FK_MISMATCH".to_owned(),
            message: "V2 animated socket appearance candidate/artifact binding differs".to_owned(),
        });
    }

    let delivery: Option<(String, String, String)> = connection
        .query_row(
            "SELECT project_id, lod0_candidate_id, lod0_artifact_sha256 FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1",
            params![game_weapon_animated_glb_socket_materialization_v2_value_string(
                &value,
                "appearance_delivery_manifest_object_sha256",
            )?],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if delivery.as_ref().map(|row| row.0.as_str())
        != Some(
            game_weapon_animated_glb_socket_materialization_v2_value_string(&value, "project_id")?,
        )
        || delivery.as_ref().map(|row| row.1.as_str())
            != Some(
                game_weapon_animated_glb_socket_materialization_v2_value_string(
                    &value,
                    "appearance_candidate_id",
                )?,
            )
        || delivery.as_ref().map(|row| row.2.as_str())
            != Some(
                game_weapon_animated_glb_socket_materialization_v2_value_string(
                    &value,
                    "appearance_artifact_sha256",
                )?,
            )
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_DELIVERY_FK_MISMATCH".to_owned(),
            message: "V2 animated socket appearance delivery binding differs".to_owned(),
        });
    }

    let anchor: Option<(String, String, String)> = connection
        .query_row(
            "SELECT project_id, lod0_artifact_sha256, anchor_set_object_sha256 FROM game_weapon_anchor_links WHERE delivery_manifest_object_sha256 = ?1",
            params![game_weapon_animated_glb_socket_materialization_v2_value_string(
                &value,
                "appearance_delivery_manifest_object_sha256",
            )?],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if anchor.as_ref().map(|row| row.0.as_str())
        != Some(
            game_weapon_animated_glb_socket_materialization_v2_value_string(&value, "project_id")?,
        )
        || anchor.as_ref().map(|row| row.1.as_str())
            != Some(
                game_weapon_animated_glb_socket_materialization_v2_value_string(
                    &value,
                    "appearance_artifact_sha256",
                )?,
            )
        || anchor.as_ref().map(|row| row.2.as_str())
            != Some(
                game_weapon_animated_glb_socket_materialization_v2_value_string(
                    &value,
                    "anchor_set_object_sha256",
                )?,
            )
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_ANCHOR_FK_MISMATCH".to_owned(),
            message: "V2 animated socket AnchorSet binding differs".to_owned(),
        });
    }
    Ok(())
}

fn validate_game_weapon_animated_glb_socket_materialization_v2_source_bindings(
    store: &Store,
    link: &GameWeaponAnimatedGlbSocketMaterializationV2LinkRecord,
    parent: &MechanicalAnimationGlbV2LinkRecord,
) -> Result<(), StoreError> {
    let value = game_weapon_animated_glb_socket_materialization_v2_value(link)?;
    let parent_value =
        serde_json::to_value(parent).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if value.get("animation_glb_key_sha256") != parent_value.get("animation_glb_key_sha256")
        || value.get("appearance_candidate_id") != parent_value.get("appearance_candidate_id")
        || value.get("appearance_artifact_sha256") != parent_value.get("appearance_artifact_sha256")
        || value.get("animated_artifact_sha256") != parent_value.get("animated_artifact_sha256")
        || value.get("animation_receipt_object_sha256") != parent_value.get("receipt_object_sha256")
        || value.get("clip_id") != parent_value.get("clip_id")
        || value.get("clip_object_sha256") != parent_value.get("clip_object_sha256")
        || value.get("clip_sha256") != parent_value.get("clip_sha256")
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_SOURCE_BINDING_MISMATCH".to_owned(),
            message: "V2 animated socket source differs from MechanicalAnimationGlb@2".to_owned(),
        });
    }
    let connection = store.lock_connection()?;
    validate_game_weapon_animated_glb_socket_materialization_v2_bindings_in_transaction(
        &connection,
        link,
    )?;
    Ok(())
}

fn game_weapon_animated_glb_socket_materialization_v2_reachable_hashes(
    connection: &Connection,
    link: &GameWeaponAnimatedGlbSocketMaterializationV2LinkRecord,
    parent: &MechanicalAnimationGlbV2LinkRecord,
) -> Result<Vec<String>, StoreError> {
    let value = game_weapon_animated_glb_socket_materialization_v2_value(link)?;
    let delivery: Option<(
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        Option<String>,
    )> = connection
        .query_row(
            "SELECT delivery_manifest_object_sha256, lod0_artifact_sha256, lod1_artifact_sha256, lod2_artifact_sha256, lod_receipt_object_sha256, collision_proxy_object_sha256, readiness_object_sha256, animation_artifact_sha256 FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1",
            params![game_weapon_animated_glb_socket_materialization_v2_value_string(
                &value,
                "appearance_delivery_manifest_object_sha256",
            )?],
            |row| {
                Ok((
                    row.get(0)?,
                    row.get(1)?,
                    row.get(2)?,
                    row.get(3)?,
                    row.get(4)?,
                    row.get(5)?,
                    row.get(6)?,
                    row.get(7)?,
                ))
            },
        )
        .optional()?;
    let Some(delivery) = delivery else {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_DELIVERY_FK_MISMATCH".to_owned(),
            message: "V2 animated socket delivery disappeared before reachability marking"
                .to_owned(),
        });
    };
    let mut hashes = vec![
        delivery.0,
        delivery.1,
        delivery.2,
        delivery.3,
        delivery.4,
        delivery.5,
        delivery.6,
        game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "appearance_artifact_sha256",
        )?
        .to_owned(),
        game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "animated_artifact_sha256",
        )?
        .to_owned(),
        game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "animation_receipt_object_sha256",
        )?
        .to_owned(),
        game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "clip_object_sha256",
        )?
        .to_owned(),
        game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "anchor_set_object_sha256",
        )?
        .to_owned(),
        game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "derived_animated_socket_artifact_sha256",
        )?
        .to_owned(),
        game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "receipt_object_sha256",
        )?
        .to_owned(),
    ];
    if let Some(animation) = delivery.7 {
        hashes.push(animation);
    }
    hashes.extend(mechanical_animation_glb_v2_reachable_hashes(parent));
    hashes.sort();
    hashes.dedup();
    validate_reachable_hashes(&hashes)?;
    Ok(hashes)
}

fn validate_game_weapon_animated_glb_socket_transform_projection(
    projection: &GameWeaponAnimatedGlbSocketTransformProjection,
) -> Result<(), StoreError> {
    let mut canonical = projection.clone();
    canonical.canonical_sha256.clear();
    let expected_canonical = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    let expected_roles = [
        "weapon-root",
        "grip-primary",
        "muzzle-vfx",
        "magazine-well",
        "sight-primary",
        "energy-core-vfx",
    ]
    .into_iter()
    .map(str::to_owned)
    .collect::<Vec<_>>();
    let expected_limitations = [
        "flat-identity-rest-part-hierarchy-only",
        "nested-part-hierarchy-rejected",
        "nonidentity-rest-part-transform-rejected",
        "matrix-and-shear-rejected",
        "structural-transform-readback-only",
        "no-visual-quality-or-likeness-pass",
        "no-commercial-engine-roundtrip",
        "no-functional-weapon-semantics",
    ]
    .into_iter()
    .map(str::to_owned)
    .collect::<Vec<_>>();
    if projection.schema_version != "GameWeaponAnimatedGlbSocketTransformProjection@1"
        || !is_sha256(&projection.projection_key_sha256)
        || !is_opaque_id(&projection.project_id)
        || !is_opaque_id(&projection.candidate_id)
        || !is_sha256(&projection.candidate_state_sha256)
        || !is_sha256(&projection.delivery_manifest_object_sha256)
        || !is_sha256(&projection.source_artifact_sha256)
        || !is_sha256(&projection.source_artifact_readback_sha256)
        || !is_sha256(&projection.animated_artifact_sha256)
        || !is_sha256(&projection.animated_artifact_readback_sha256)
        || !is_sha256(&projection.animation_receipt_object_sha256)
        || !is_sha256(&projection.animation_receipt_canonical_sha256)
        || !is_sha256(&projection.animated_socket_materialization_key_sha256)
        || !is_sha256(&projection.derived_animated_socket_artifact_sha256)
        || !is_sha256(&projection.derived_animated_socket_artifact_readback_sha256)
        || !is_sha256(&projection.derived_animated_socket_receipt_object_sha256)
        || !is_sha256(&projection.derived_animated_socket_receipt_canonical_sha256)
        || !is_sha256(&projection.anchor_set_object_sha256)
        || !is_sha256(&projection.anchor_set_canonical_sha256)
        || !is_opaque_id(&projection.animation_clip_id)
        || !is_sha256(&projection.animation_clip_object_sha256)
        || !is_sha256(&projection.animation_clip_canonical_sha256)
        || !is_sha256(&projection.socket_node_id_encoding_sha256)
        || !is_sha256(&projection.socket_node_inventory_sha256)
        || !is_sha256(&projection.socket_roles_sha256)
        || projection.socket_roles != expected_roles
        || !is_sha256(&projection.part_hierarchy_sha256)
        || projection.part_hierarchy_policy != "flat-identity-rest-part-hierarchy-only@1"
        || projection.transform_representation_policy != "trs-quaternion-no-matrix-no-shear@1"
        || !is_sha256(&projection.sample_schedule_sha256)
        || !(1..=16).contains(&projection.sample_count)
        || projection.sample_time_ticks.len() != projection.sample_count as usize
        || projection
            .sample_time_ticks
            .windows(2)
            .any(|ticks| ticks[0] >= ticks[1])
        || projection
            .sample_time_ticks
            .iter()
            .any(|tick| *tick > 1_000_000)
        || projection.frame_scope
            != GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_FRAME_SCOPE
        || projection.timebase_hz != 1000
        || projection.transform_projection_policy
            != GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_POLICY
        || projection.coordinate_system != "forgecad-rh-y-up-m@1"
        || projection.transform_convention
            != "column-vector-parent-world-times-trs-quaternion-xyzw@1"
        || projection.float_quantization_policy != "f32-round-nearest-canonical-json@1"
        || !is_sha256(&projection.input_sha256)
        || projection.frames.len() != projection.sample_count as usize
        || projection.projection_status
            != GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_STATUS
        || projection.quality_status != "structural_only"
        || projection.visual_quality_status != "NOT_PROVEN"
        || projection.commercial_fps_quality_status != "NOT_PROVEN"
        || projection.human_review_status != "NOT_RUN"
        || projection.commercial_engine_status != "NOT_RUN"
        || !projection.runtime_write_performed
        || !projection.restart_hash_verified
        || projection.candidate_confirmed
        || projection.version_created
        || projection.export_performed
        || projection.actual_engine_roundtrip
        || projection.production_stage_advanced
        || projection.limitations != expected_limitations
        || projection.canonical_sha256 != expected_canonical
        || projection.created_at.is_empty()
        || projection.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "game weapon animated GLB socket transform projection is malformed".to_owned(),
        ));
    }
    for (ordinal, frame) in projection.frames.iter().enumerate() {
        validate_game_weapon_animated_glb_socket_transform_projection_frame(
            frame,
            &projection.projection_key_sha256,
            ordinal,
            projection.sample_time_ticks[ordinal],
            &projection.socket_roles,
        )?;
    }
    Ok(())
}

fn validate_game_weapon_animated_glb_socket_transform_projection_frame(
    frame: &GameWeaponAnimatedGlbSocketTransformProjectionFrame,
    projection_key_sha256: &str,
    ordinal: usize,
    expected_sample_time_ticks: u64,
    socket_roles: &[String],
) -> Result<(), StoreError> {
    let mut canonical = frame.clone();
    canonical.canonical_sha256.clear();
    let expected_canonical = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    if frame.schema_version != "GameWeaponAnimatedGlbSocketTransformProjectionFrame@1"
        || frame.projection_key_sha256 != projection_key_sha256
        || frame.frame_index != ordinal as u64
        || frame.sample_time_ticks != expected_sample_time_ticks
        || !is_sha256(&frame.source_animation_sample_sha256)
        || !is_sha256(&frame.derived_socket_sample_sha256)
        || !is_sha256(&frame.socket_transform_inventory_sha256)
        || !is_sha256(&frame.socket_transform_readback_sha256)
        || frame.socket_transforms.len() != 6
        || frame.canonical_sha256 != expected_canonical
        || frame.created_at.is_empty()
        || frame.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "game weapon animated GLB socket transform projection frame is malformed".to_owned(),
        ));
    }
    let mut seen_roles = HashSet::new();
    let mut seen_nodes = HashSet::new();
    let mut seen_anchors = HashSet::new();
    for socket in &frame.socket_transforms {
        if !is_opaque_id(&socket.socket_node_id)
            || !is_opaque_id(&socket.anchor_id)
            || !is_opaque_id(&socket.role)
            || !socket_roles.iter().any(|role| role == &socket.role)
            || !seen_roles.insert(socket.role.clone())
            || !seen_nodes.insert(socket.socket_node_id.clone())
            || !seen_anchors.insert(socket.anchor_id.clone())
            || socket.node_index > 4095
            || socket.parent_node_index < -1
            || socket.parent_node_index > 4095
            || !is_opaque_id(&socket.node_name)
            || socket
                .parent_node_name
                .as_deref()
                .is_some_and(|name| !is_opaque_id(name))
            || socket.node_kind != "empty"
            || !matches!(
                socket.parent_kind.as_str(),
                "synthetic-scene-root" | "part-node"
            )
            || socket
                .owner_part_id
                .as_deref()
                .is_some_and(|part_id| !is_opaque_id(part_id))
            || !validate_game_weapon_animated_glb_socket_transform_projection_pose(
                &socket.local_transform,
            )
            || !validate_game_weapon_animated_glb_socket_transform_projection_pose(
                &socket.parent_world_transform,
            )
            || !validate_game_weapon_animated_glb_socket_transform_projection_pose(
                &socket.composed_world_transform,
            )
        {
            return Err(StoreError::InvalidData(
                "game weapon animated GLB socket transform is malformed".to_owned(),
            ));
        }
    }
    if seen_roles.len() != socket_roles.len() {
        return Err(StoreError::InvalidData(
            "game weapon animated GLB socket roles are incomplete".to_owned(),
        ));
    }
    Ok(())
}

fn validate_game_weapon_animated_glb_socket_transform_projection_pose(
    pose: &forgecad_contracts::GameWeaponAnimatedGlbSocketTransformProjectionPose,
) -> bool {
    pose.translation_m.len() == 3
        && pose.rotation_quat_xyzw.len() == 4
        && pose.scale_xyz == [1.0, 1.0, 1.0]
        && pose
            .translation_m
            .iter()
            .all(|value| value.is_finite() && (-1000.0..=1000.0).contains(value))
        && pose
            .rotation_quat_xyzw
            .iter()
            .all(|value| value.is_finite() && (-1.0..=1.0).contains(value))
        && {
            let norm = pose
                .rotation_quat_xyzw
                .iter()
                .map(|value| value * value)
                .sum::<f64>()
                .sqrt();
            (norm - 1.0).abs() <= 0.0001
        }
}

fn validate_game_weapon_animated_glb_socket_transform_projection_object(
    bytes: &[u8],
    projection: &GameWeaponAnimatedGlbSocketTransformProjection,
    object: &CasObjectRecord,
) -> Result<(), StoreError> {
    if object.schema_version != "CasObject@1"
        || !is_sha256(&object.sha256)
        || object.mime != GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_MIME
        || object.kind != GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_KIND
        || object.size_bytes == 0
        || object.size_bytes > MAX_GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_BYTES
        || object.size_bytes != bytes.len() as u64
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
        || object.created_at.is_empty()
        || object.created_at.len() > 64
        || sha256_hex(bytes) != object.sha256
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_OBJECT_INVALID".to_owned(),
            message: "transform projection CAS metadata or bytes are invalid".to_owned(),
        });
    }
    let value: Value = serde_json::from_slice(bytes).map_err(|error| StoreError::Contract {
        code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_OBJECT_INVALID".to_owned(),
        message: format!("transform projection JSON is invalid: {error}"),
    })?;
    let canonical_bytes =
        canonical_json_bytes(&value).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if canonical_bytes != bytes {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_OBJECT_CANONICAL_MISMATCH"
                .to_owned(),
            message: "transform projection JSON is not canonical".to_owned(),
        });
    }
    let decoded: GameWeaponAnimatedGlbSocketTransformProjection = serde_json::from_value(value)
        .map_err(|error| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_OBJECT_INVALID".to_owned(),
            message: format!("transform projection JSON shape is invalid: {error}"),
        })?;
    if decoded != *projection {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_OBJECT_BINDING_MISMATCH"
                .to_owned(),
            message: "transform projection CAS bytes differ from the typed projection".to_owned(),
        });
    }
    Ok(())
}

fn projection_row_u64(row: &rusqlite::Row<'_>, index: usize) -> rusqlite::Result<u64> {
    let value: i64 = row.get(index)?;
    u64::try_from(value).map_err(|_| {
        rusqlite::Error::FromSqlConversionFailure(
            index,
            rusqlite::types::Type::Integer,
            "projection integer is outside u64 range".into(),
        )
    })
}

fn projection_row_json<T: serde::de::DeserializeOwned>(
    row: &rusqlite::Row<'_>,
    index: usize,
) -> rusqlite::Result<T> {
    let value: String = row.get(index)?;
    serde_json::from_str(&value).map_err(|error| {
        rusqlite::Error::FromSqlConversionFailure(
            index,
            rusqlite::types::Type::Text,
            Box::new(error),
        )
    })
}

