fn read_game_weapon_animated_glb_socket_transform_projection_frames(
    connection: &Connection,
    projection_key_sha256: &str,
) -> Result<Vec<GameWeaponAnimatedGlbSocketTransformProjectionFrame>, StoreError> {
    let mut statement = connection.prepare(
        "SELECT projection_key_sha256, schema_version, frame_index, sample_time_ticks, source_animation_sample_sha256, derived_socket_sample_sha256, socket_transform_inventory_sha256, socket_transform_readback_sha256, socket_transforms_json, canonical_sha256, created_at FROM game_weapon_animated_glb_socket_transform_projection_frames WHERE projection_key_sha256 = ?1 ORDER BY frame_index ASC",
    )?;
    let rows = statement.query_map(
        params![projection_key_sha256],
        game_weapon_animated_glb_socket_transform_projection_frame_from_row,
    )?;
    rows.collect::<Result<Vec<_>, _>>()
        .map_err(StoreError::Sqlite)
}

fn same_game_weapon_animated_glb_socket_transform_projection(
    left: &GameWeaponAnimatedGlbSocketTransformProjection,
    right: &GameWeaponAnimatedGlbSocketTransformProjection,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    for frame in &mut left.frames {
        frame.created_at.clear();
        frame.canonical_sha256.clear();
    }
    for frame in &mut right.frames {
        frame.created_at.clear();
        frame.canonical_sha256.clear();
    }
    left == right
}

fn game_weapon_animated_glb_socket_transform_projection_reachable_hashes(
    projection: &GameWeaponAnimatedGlbSocketTransformProjection,
    projection_object_sha256: Option<&str>,
) -> Vec<String> {
    let mut hashes = vec![
        projection.source_artifact_sha256.clone(),
        projection.animated_artifact_sha256.clone(),
        projection.animation_receipt_object_sha256.clone(),
        projection.derived_animated_socket_artifact_sha256.clone(),
        projection
            .derived_animated_socket_receipt_object_sha256
            .clone(),
        projection.anchor_set_object_sha256.clone(),
        projection.animation_clip_object_sha256.clone(),
    ];
    if let Some(hash) = projection_object_sha256 {
        hashes.push(hash.to_owned());
    }
    hashes
}

fn game_weapon_animated_glb_socket_transform_projection_v2_from_payload(
    payload: &str,
) -> Result<GameWeaponAnimatedGlbSocketTransformProjectionV2, StoreError> {
    let value: Value = serde_json::from_str(payload).map_err(|error| {
        StoreError::InvalidData(format!("invalid V2 transform projection payload: {error}"))
    })?;
    let projection: GameWeaponAnimatedGlbSocketTransformProjectionV2 =
        serde_json::from_value(value.clone()).map_err(|error| {
            StoreError::InvalidData(format!("invalid V2 transform projection payload: {error}"))
        })?;
    let typed_value = serde_json::to_value(&projection)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    let canonical_payload = canonical_json_bytes(&typed_value)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if typed_value != value || canonical_payload.as_slice() != payload.as_bytes() {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_PAYLOAD_MISMATCH"
                .to_owned(),
            message: "V2 projection payload is not the exact typed canonical record".to_owned(),
        });
    }
    Ok(projection)
}

fn validate_game_weapon_animated_glb_socket_transform_projection_v2_parent_columns(
    columns: &str,
    projection: &GameWeaponAnimatedGlbSocketTransformProjectionV2,
) -> Result<(), StoreError> {
    let columns: Value = serde_json::from_str(columns).map_err(|error| StoreError::Contract {
        code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SQL_ROW_INVALID".to_owned(),
        message: format!("V2 projection SQLite scalar row is invalid: {error}"),
    })?;
    let expected = serde_json::to_value(projection)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    const FIELDS: &[&str] = &[
        "schema_version",
        "projection_key_sha256",
        "project_id",
        "appearance_candidate_id",
        "appearance_candidate_state_sha256",
        "appearance_delivery_manifest_object_sha256",
        "appearance_artifact_sha256",
        "appearance_artifact_readback_sha256",
        "animation_clip_id",
        "animation_clip_object_sha256",
        "animation_clip_canonical_sha256",
        "animation_glb_key_sha256",
        "animated_artifact_sha256",
        "animated_artifact_readback_sha256",
        "animation_receipt_object_sha256",
        "animation_receipt_canonical_sha256",
        "animated_socket_materialization_key_sha256",
        "derived_animated_socket_artifact_sha256",
        "derived_animated_socket_artifact_readback_sha256",
        "derived_animated_socket_receipt_object_sha256",
        "derived_animated_socket_receipt_canonical_sha256",
        "anchor_set_object_sha256",
        "anchor_set_canonical_sha256",
        "socket_node_id_encoding_sha256",
        "socket_node_inventory_sha256",
        "socket_roles_sha256",
        "sampling_policy_sha256",
        "sample_schedule_sha256",
        "sample_count",
        "frame_scope",
        "transform_projection_policy",
        "input_sha256",
        "projection_status",
        "canonical_sha256",
        "created_at",
    ];
    for field in FIELDS {
        if columns.get(*field) != expected.get(*field) {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SQL_ROW_MISMATCH"
                    .to_owned(),
                message: format!("V2 projection SQLite scalar {field} differs from payload"),
            });
        }
    }
    let stored_ticks = columns
        .get("sample_time_ticks_json")
        .and_then(Value::as_str)
        .ok_or_else(|| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SQL_ROW_MISMATCH"
                .to_owned(),
            message: "V2 projection SQLite sample ticks scalar is missing".to_owned(),
        })?;
    let stored_ticks: Value =
        serde_json::from_str(stored_ticks).map_err(|error| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SQL_ROW_MISMATCH"
                .to_owned(),
            message: format!("V2 projection SQLite sample ticks scalar is invalid: {error}"),
        })?;
    if stored_ticks != expected["sample_time_ticks"] {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SQL_ROW_MISMATCH"
                .to_owned(),
            message: "V2 projection SQLite sample ticks differ from payload".to_owned(),
        });
    }
    Ok(())
}

