fn read_game_weapon_glb_socket_materialization_lods(
    connection: &Connection,
    key: &str,
) -> Result<Vec<GameWeaponGlbSocketMaterializationLodRecord>, StoreError> {
    let mut statement = connection.prepare(
        "SELECT socket_materialization_key_sha256, lod_level, source_candidate_id, source_candidate_state_sha256, source_artifact_sha256, source_artifact_readback_sha256, derived_artifact_sha256, derived_artifact_readback_sha256, source_renderable_inventory_sha256, derived_renderable_inventory_sha256, socket_node_inventory_sha256, canonical_sha256, created_at FROM game_weapon_glb_socket_materialization_lods WHERE socket_materialization_key_sha256 = ?1 ORDER BY lod_level ASC",
    )?;
    let rows = statement.query_map(
        params![key],
        game_weapon_glb_socket_materialization_lod_from_row,
    )?;
    Ok(rows.collect::<Result<Vec<_>, _>>()?)
}

fn same_game_weapon_glb_socket_materialization_link(
    left: &GameWeaponGlbSocketMaterializationLinkRecord,
    right: &GameWeaponGlbSocketMaterializationLinkRecord,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left == right
}

fn same_game_weapon_glb_socket_materialization_lods(
    left: &[GameWeaponGlbSocketMaterializationLodRecord],
    right: &[GameWeaponGlbSocketMaterializationLodRecord],
) -> bool {
    if left.len() != right.len() {
        return false;
    }
    left.iter().zip(right).all(|(left, right)| {
        let mut left = left.clone();
        let mut right = right.clone();
        left.created_at.clear();
        right.created_at.clear();
        left.canonical_sha256.clear();
        right.canonical_sha256.clear();
        left == right
    })
}

fn game_weapon_glb_socket_materialization_reachable_hashes(
    link: &GameWeaponGlbSocketMaterializationLinkRecord,
    lods: &[GameWeaponGlbSocketMaterializationLodRecord],
) -> Vec<String> {
    let mut hashes = vec![link.receipt_object_sha256.clone()];
    hashes.extend(lods.iter().map(|lod| lod.derived_artifact_sha256.clone()));
    hashes
}

fn ensure_game_weapon_glb_socket_materialization_object(
    connection: &Connection,
    sha256: &str,
    expected_mime: &str,
    expected_kind: &str,
    max_bytes: i64,
) -> Result<(), StoreError> {
    let metadata: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if !metadata.is_some_and(|(size, mime, kind, reachability)| {
        size > 0
            && size <= max_bytes
            && mime == expected_mime
            && kind == expected_kind
            && matches!(reachability.as_str(), "temporary" | "reachable")
    }) {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_GLB_SOCKET_CAS_OBJECT_INVALID".to_owned(),
            message: "socket materialization CAS metadata is missing or differs".to_owned(),
        });
    }
    Ok(())
}

fn ensure_game_weapon_glb_socket_source_object(
    connection: &Connection,
    sha256: &str,
) -> Result<(), StoreError> {
    let metadata: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if !metadata.is_some_and(|(size, mime, kind, reachability)| {
        size > 0
            && size <= 64 * 1024 * 1024
            && mime == "model/gltf-binary"
            && matches!(
                kind.as_str(),
                "geometry-glb" | "appearance-glb" | "appearance-v2-glb"
            )
            && matches!(reachability.as_str(), "temporary" | "reachable")
    }) {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_GLB_SOCKET_SOURCE_ARTIFACT_INVALID".to_owned(),
            message: "socket materialization source GLB metadata is invalid".to_owned(),
        });
    }
    Ok(())
}

fn ensure_game_weapon_glb_socket_materialization_objects(
    connection: &Connection,
    link: &GameWeaponGlbSocketMaterializationLinkRecord,
    lods: &[GameWeaponGlbSocketMaterializationLodRecord],
) -> Result<(), StoreError> {
    ensure_game_weapon_glb_socket_materialization_object(
        connection,
        &link.anchor_set_object_sha256,
        GAME_ASSET_DELIVERY_JSON_MIME,
        GAME_WEAPON_ANCHOR_SET_KIND,
        i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
    )?;
    ensure_game_weapon_glb_socket_materialization_object(
        connection,
        &link.receipt_object_sha256,
        GAME_ASSET_DELIVERY_JSON_MIME,
        GAME_WEAPON_GLB_SOCKET_MATERIALIZATION_RECEIPT_KIND,
        i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
    )?;
    for lod in lods {
        ensure_game_weapon_glb_socket_source_object(connection, &lod.source_artifact_sha256)?;
        ensure_game_weapon_glb_socket_materialization_object(
            connection,
            &lod.derived_artifact_sha256,
            "model/gltf-binary",
            GAME_WEAPON_GLB_SOCKET_MATERIALIZED_GLB_KIND,
            64 * 1024 * 1024,
        )?;
    }
    Ok(())
}

fn validate_game_weapon_glb_socket_materialization_binding_in_transaction(
    connection: &Connection,
    link: &GameWeaponGlbSocketMaterializationLinkRecord,
    lods: &[GameWeaponGlbSocketMaterializationLodRecord],
) -> Result<(), StoreError> {
    let delivery: Option<(String, [String; 3], [String; 3])> = connection
        .query_row(
            "SELECT project_id, lod0_candidate_id, lod1_candidate_id, lod2_candidate_id, lod0_artifact_sha256, lod1_artifact_sha256, lod2_artifact_sha256 FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1",
            params![link.delivery_manifest_object_sha256],
            |row| {
                Ok((
                    row.get(0)?,
                    [row.get(1)?, row.get(2)?, row.get(3)?],
                    [row.get(4)?, row.get(5)?, row.get(6)?],
                ))
            },
        )
        .optional()?;
    let Some((delivery_project, delivery_candidates, delivery_artifacts)) = delivery else {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_GLB_SOCKET_DELIVERY_BINDING_MISMATCH".to_owned(),
            message: "socket materialization delivery link is unavailable".to_owned(),
        });
    };
    if delivery_project != link.project_id {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_GLB_SOCKET_DELIVERY_BINDING_MISMATCH".to_owned(),
            message: "socket materialization project differs from delivery".to_owned(),
        });
    }
    let anchor: Option<(String, String)> = connection
        .query_row(
            "SELECT project_id, anchor_set_object_sha256 FROM game_weapon_anchor_links WHERE delivery_manifest_object_sha256 = ?1",
            params![link.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    if anchor.as_ref().map(|value| value.0.as_str()) != Some(link.project_id.as_str())
        || anchor.as_ref().map(|value| value.1.as_str())
            != Some(link.anchor_set_object_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_GLB_SOCKET_ANCHOR_BINDING_MISMATCH".to_owned(),
            message: "socket materialization AnchorSet differs from durable anchor link".to_owned(),
        });
    }
    for lod in lods {
        let level = usize::try_from(lod.lod_level).map_err(|_| {
            StoreError::InvalidData("socket materialization LOD level is invalid".to_owned())
        })?;
        let candidate: Option<(String, String, Option<String>, Option<String>)> = connection
            .query_row(
                "SELECT project_id, canonical_sha256, prepared_object_sha256, manifest_hash FROM candidates WHERE candidate_id = ?1",
                params![lod.source_candidate_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .optional()?;
        let Some((candidate_project, candidate_state, prepared, manifest)) = candidate else {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_GLB_SOCKET_CANDIDATE_BINDING_MISMATCH".to_owned(),
                message: "socket materialization source candidate is unavailable".to_owned(),
            });
        };
        if candidate_project != link.project_id
            || candidate_state != lod.source_candidate_state_sha256
            || prepared.as_deref() != Some(lod.source_artifact_sha256.as_str())
            || manifest.as_deref() != Some(lod.source_artifact_sha256.as_str())
            || delivery_candidates[level] != lod.source_candidate_id
            || delivery_artifacts[level] != lod.source_artifact_sha256
        {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_GLB_SOCKET_CANDIDATE_BINDING_MISMATCH".to_owned(),
                message:
                    "socket materialization source candidate/artifact binding differs from delivery"
                        .to_owned(),
            });
        }
    }
    Ok(())
}

