        || !is_sha256(&link.bloom_profile_sha256)
        || !is_sha256(&link.render_set_object_sha256)
        || !is_sha256(&link.receipt_object_sha256)
        || !is_sha256(&link.source_object_sha256)
        || !is_sha256(&link.contribution_object_sha256)
        || link.materialization_status
            != "runtime-owned-durable-fictional-energy-vfx-hdr-bloom-frame"
