fn validate_fictional_energy_vfx_trails_frame_binding_in_transaction(
    connection: &Connection,
    link: &FictionalEnergyVfxTrailsFrameLinkRecord,
) -> Result<(), StoreError> {
    let delivery: Option<(String, String, String)> = connection
        .query_row(
            "SELECT project_id, lod0_candidate_id, lod0_artifact_sha256 FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1",
            params![link.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if delivery.as_ref().map(|value| value.0.as_str()) != Some(link.project_id.as_str())
        || delivery.as_ref().map(|value| value.1.as_str())
            != Some(link.source_candidate_id.as_str())
        || delivery.as_ref().map(|value| value.2.as_str())
            != Some(link.source_artifact_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_TRAILS_DELIVERY_BINDING_MISMATCH".to_owned(),
            message: "trail project/candidate/artifact differs from durable LOD0".to_owned(),
        });
    }
    let profile: Option<(String, String, String)> = connection
        .query_row(
            "SELECT project_id, vfx_profile_object_sha256, anchor_set_object_sha256 FROM fictional_energy_vfx_links WHERE delivery_manifest_object_sha256 = ?1",
            params![link.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if profile.as_ref().map(|value| value.0.as_str()) != Some(link.project_id.as_str())
        || profile.as_ref().map(|value| value.1.as_str())
            != Some(link.vfx_profile_object_sha256.as_str())
        || profile.as_ref().map(|value| value.2.as_str())
            != Some(link.anchor_set_object_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_TRAILS_PROFILE_BINDING_MISMATCH".to_owned(),
            message: "trail project/profile/AnchorSet binding differs".to_owned(),
        });
    }
    let base: Option<(String, String, String, String, String, String, String, String, String)> =
        connection
            .query_row(
                "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, source_candidate_id, source_artifact_sha256, camera_object_sha256, camera_identity_sha256, render_profile_sha256, render_worker_build_cohort_sha256 FROM fictional_energy_vfx_frame_links WHERE frame_key_sha256 = ?1",
                params![link.base_frame_key_sha256],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?)),
            )
            .optional()?;
    if base.as_ref().map(|value| value.0.as_str()) != Some(link.project_id.as_str())
        || base.as_ref().map(|value| value.1.as_str())
            != Some(link.delivery_manifest_object_sha256.as_str())
        || base.as_ref().map(|value| value.2.as_str())
            != Some(link.vfx_profile_object_sha256.as_str())
        || base.as_ref().map(|value| value.3.as_str()) != Some(link.source_candidate_id.as_str())
        || base.as_ref().map(|value| value.4.as_str()) != Some(link.source_artifact_sha256.as_str())
        || base.as_ref().map(|value| value.5.as_str()) != Some(link.camera_object_sha256.as_str())
        || base.as_ref().map(|value| value.6.as_str()) != Some(link.camera_identity_sha256.as_str())
        || base.as_ref().map(|value| value.7.as_str()) != Some(link.render_profile_sha256.as_str())
        || base.as_ref().map(|value| value.8.as_str())
            != Some(link.render_worker_build_cohort_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_TRAILS_BASE_BINDING_MISMATCH".to_owned(),
            message: "trail base frame binding differs".to_owned(),
        });
    }
    let bloom: Option<(String, String, String, String, String, String, String, String)> =
        connection
            .query_row(
                "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, source_candidate_id, source_artifact_sha256, base_frame_key_sha256, camera_identity_sha256, render_worker_build_cohort_sha256 FROM fictional_energy_vfx_bloom_frame_links WHERE bloom_key_sha256 = ?1",
                params![link.bloom_key_sha256],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?)),
            )
            .optional()?;
    if bloom.as_ref().map(|value| value.0.as_str()) != Some(link.project_id.as_str())
        || bloom.as_ref().map(|value| value.1.as_str())
            != Some(link.delivery_manifest_object_sha256.as_str())
        || bloom.as_ref().map(|value| value.2.as_str())
            != Some(link.vfx_profile_object_sha256.as_str())
        || bloom.as_ref().map(|value| value.3.as_str()) != Some(link.source_candidate_id.as_str())
        || bloom.as_ref().map(|value| value.4.as_str())
            != Some(link.source_artifact_sha256.as_str())
        || bloom.as_ref().map(|value| value.5.as_str()) != Some(link.base_frame_key_sha256.as_str())
        || bloom.as_ref().map(|value| value.6.as_str())
            != Some(link.camera_identity_sha256.as_str())
        || bloom.as_ref().map(|value| value.7.as_str())
            != Some(link.render_worker_build_cohort_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_TRAILS_BLOOM_BINDING_MISMATCH".to_owned(),
            message: "trail HDR bloom binding differs".to_owned(),
        });
    }
    let particle_keys = std::iter::once((&link.current_particle_key_sha256, true)).chain(
        link.particle_history_key_sha256s
            .iter()
            .map(|particle_key| (particle_key, false)),
    );
    for (particle_key, is_current) in particle_keys {
        let particle: Option<(
            String,
            String,
            String,
            String,
            String,
            String,
            String,
            String,
            String,
            String,
            String,
            String,
        )> =
            connection
                .query_row(
                    "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, source_candidate_id, source_artifact_sha256, base_frame_key_sha256, bloom_key_sha256, render_worker_build_cohort_sha256, anchor_set_object_sha256, camera_object_sha256, camera_identity_sha256, render_profile_sha256 FROM fictional_energy_vfx_particles_frame_links WHERE particle_key_sha256 = ?1",
                    params![particle_key],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?, row.get(9)?, row.get(10)?, row.get(11)?)),
                )
                .optional()?;
        if particle.as_ref().map(|value| value.0.as_str()) != Some(link.project_id.as_str())
            || particle.as_ref().map(|value| value.1.as_str())
                != Some(link.delivery_manifest_object_sha256.as_str())
            || particle.as_ref().map(|value| value.2.as_str())
                != Some(link.vfx_profile_object_sha256.as_str())
            || particle.as_ref().map(|value| value.3.as_str())
                != Some(link.source_candidate_id.as_str())
            || particle.as_ref().map(|value| value.4.as_str())
                != Some(link.source_artifact_sha256.as_str())
            || particle.as_ref().map(|value| value.7.as_str())
                != Some(link.render_worker_build_cohort_sha256.as_str())
            || particle.as_ref().map(|value| value.8.as_str())
                != Some(link.anchor_set_object_sha256.as_str())
            || particle.as_ref().map(|value| value.9.as_str())
                != Some(link.camera_object_sha256.as_str())
            || particle.as_ref().map(|value| value.10.as_str())
                != Some(link.camera_identity_sha256.as_str())
            || particle.as_ref().map(|value| value.11.as_str())
                != Some(link.render_profile_sha256.as_str())
            || (is_current
                && (particle.as_ref().map(|value| value.5.as_str())
                    != Some(link.base_frame_key_sha256.as_str())
                    || particle.as_ref().map(|value| value.6.as_str())
                        != Some(link.bloom_key_sha256.as_str())))
        {
            return Err(StoreError::Contract {
                code: "FICTIONAL_ENERGY_VFX_TRAILS_PARTICLE_BINDING_MISMATCH".to_owned(),
                message: "trail current/history particle binding differs".to_owned(),
            });
        }
    }
    Ok(())
}

