fn read_fictional_energy_vfx_animated_socket_attachment_frames(
    connection: &Connection,
    attachment_key_sha256: &str,
) -> Result<Vec<FictionalEnergyVfxAnimatedSocketAttachmentFrameRecord>, StoreError> {
    let mut statement = connection.prepare(
        "SELECT attachment_key_sha256, frame_index, sample_time_ticks, animation_pose_readback_sha256, socket_transform_inventory_sha256, socket_transform_readback_sha256, emitter_socket_bindings_sha256, trail_socket_bindings_sha256, base_frame_key_sha256, bloom_key_sha256, particle_key_sha256, trail_key_sha256, trail_bloom_key_sha256, canonical_sha256, created_at FROM fictional_energy_vfx_animated_socket_attachment_frames WHERE attachment_key_sha256 = ?1 ORDER BY frame_index ASC",
    )?;
    let rows = statement.query_map(
        params![attachment_key_sha256],
        fictional_energy_vfx_animated_socket_attachment_frame_from_row,
    )?;
    rows.collect::<Result<Vec<_>, _>>()
        .map_err(StoreError::Sqlite)
}

fn same_fictional_energy_vfx_animated_socket_attachment(
    left: &FictionalEnergyVfxAnimatedSocketAttachmentRecord,
    right: &FictionalEnergyVfxAnimatedSocketAttachmentRecord,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    for frame in &mut left.frames {
        frame.created_at.clear();
        frame.canonical_sha256.clear();
    }
    for frame in &mut right.frames {
        frame.created_at.clear();
        frame.canonical_sha256.clear();
    }
    left == right
}

