fn validate_fictional_energy_vfx_animated_socket_attachment_v3_binding_in_transaction(
    connection: &Connection,
    attachment: &FictionalEnergyVfxAnimatedSocketAttachmentV3Record,
) -> Result<(), StoreError> {
    let key_is_cas: i64 = connection.query_row(
        "SELECT COUNT(*) FROM objects WHERE sha256 = ?1",
        params![attachment.attachment_key_sha256],
        |row| row.get(0),
    )?;
    if key_is_cas != 0 {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_KEY_IS_CAS",
            "Attachment@3 lookup key must not be a CAS object",
        ));
    }
    let delivery_matches = |delivery: &str, candidate: &str, artifact: &str| {
        connection
            .query_row(
                "SELECT COUNT(*) FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1 AND project_id = ?2 AND lod0_candidate_id = ?3 AND lod0_artifact_sha256 = ?4",
                params![delivery, attachment.project_id, candidate, artifact],
                |row| row.get::<_, i64>(0),
            )
            .map(|count| count == 1)
            .map_err(StoreError::Sqlite)
    };
    if !delivery_matches(
        &attachment.geometry_delivery_manifest_object_sha256,
        &attachment.geometry_candidate_id,
        &attachment.geometry_artifact_sha256,
    )? || !delivery_matches(
        &attachment.appearance_delivery_manifest_object_sha256,
        &attachment.appearance_candidate_id,
        &attachment.appearance_artifact_sha256,
    )? {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_DELIVERY_BINDING_MISMATCH",
            "Attachment@3 geometry/appearance delivery binding differs",
        ));
    }
    for (candidate_id, state, artifact) in [
        (
            &attachment.geometry_candidate_id,
            &attachment.geometry_candidate_state_sha256,
            &attachment.geometry_artifact_sha256,
        ),
        (
            &attachment.appearance_candidate_id,
            &attachment.appearance_candidate_state_sha256,
            &attachment.appearance_artifact_sha256,
        ),
    ] {
        let candidate: Option<(String, String, Option<String>, Option<String>)> = connection
            .query_row(
                "SELECT project_id, canonical_sha256, prepared_object_sha256, manifest_hash FROM candidates WHERE candidate_id = ?1",
                params![candidate_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .optional()?;
        if !candidate.is_some_and(|row| {
            row.0 == attachment.project_id
                && row.1 == *state
                && row.2.as_deref() == Some(artifact.as_str())
                && row.3.as_deref() == Some(artifact.as_str())
        }) {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_CANDIDATE_BINDING_MISMATCH",
                "Attachment@3 candidate/state/artifact binding differs",
            ));
        }
    }
    let artifact_metadata = |artifact: &str| -> Result<(), StoreError> {
        let metadata: Option<(i64, String, String, String)> = connection
            .query_row(
                "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
                params![artifact],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .optional()?;
        if !metadata.is_some_and(|(size, mime, kind, reachability)| {
            size > 0
                && size <= 64 * 1024 * 1024
                && mime == "model/gltf-binary"
                && matches!(
                    kind.as_str(),
                    "geometry-glb" | "appearance-glb" | "appearance-v2-glb"
                )
                && matches!(reachability.as_str(), "temporary" | "reachable")
        }) {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_ARTIFACT_METADATA_INVALID",
                "Attachment@3 source artifact metadata is unavailable or has an invalid kind",
            ));
        }
        Ok(())
    };
    artifact_metadata(&attachment.geometry_artifact_sha256)?;
    artifact_metadata(&attachment.appearance_artifact_sha256)?;

    let quality: Option<(String, String, String, String, String, String, String)> = connection
        .query_row(
            "SELECT project_id, source_candidate_id, source_artifact_sha256, output_candidate_id, output_artifact_sha256, report_object_sha256, canonical_sha256 FROM candidate_material_surface_quality_links WHERE material_surface_quality_id = ?1",
            params![attachment.material_surface_quality_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?)),
        )
        .optional()?;
    if !quality.is_some_and(|row| {
        row.0 == attachment.project_id
            && row.1 == attachment.geometry_candidate_id
            && row.2 == attachment.geometry_artifact_sha256
            && row.3 == attachment.appearance_candidate_id
            && row.4 == attachment.appearance_artifact_sha256
            && row.5 == attachment.material_surface_quality_report_object_sha256
            && row.6 == attachment.material_surface_quality_canonical_sha256
    }) {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_MATERIAL_QUALITY_BINDING_MISMATCH",
            "Attachment@3 material-surface quality binding differs",
        ));
    }
    let quality_report_exists: i64 = connection.query_row(
        "SELECT COUNT(*) FROM objects WHERE sha256 = ?1 AND mime = 'application/json' AND kind = 'candidate-material-surface-quality-report'",
        params![attachment.material_surface_quality_report_object_sha256],
        |row| row.get(0),
    )?;
    if quality_report_exists != 1 {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_MATERIAL_QUALITY_REPORT_MISSING",
            "Attachment@3 material-surface quality report CAS object is unavailable",
        ));
    }

    let socket: Option<(String, String, String, String, String, String, String, String, String, String, String, String, String)> = connection
        .query_row(
            "SELECT project_id, appearance_candidate_id, appearance_candidate_state_sha256, appearance_delivery_manifest_object_sha256, appearance_artifact_sha256, animated_artifact_sha256, animation_receipt_object_sha256, animation_receipt_canonical_sha256, clip_id, clip_object_sha256, clip_sha256, anchor_set_object_sha256, anchor_set_canonical_sha256 FROM game_weapon_animated_glb_socket_materialization_v2_links WHERE animated_socket_materialization_key_sha256 = ?1",
            params![attachment.animated_socket_materialization_key_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?, row.get(9)?, row.get(10)?, row.get(11)?, row.get(12)?)),
        )
        .optional()?;
    if !socket.is_some_and(|row| {
        row.0 == attachment.project_id
            && row.1 == attachment.appearance_candidate_id
            && row.2 == attachment.appearance_candidate_state_sha256
            && row.3 == attachment.appearance_delivery_manifest_object_sha256
            && row.4 == attachment.appearance_artifact_sha256
            && row.5 == attachment.animated_artifact_sha256
            && row.6 == attachment.animation_receipt_object_sha256
            && row.7 == attachment.animation_receipt_canonical_sha256
            && row.8 == attachment.animation_clip_id
            && row.9 == attachment.animation_clip_object_sha256
            && row.10 == attachment.animation_clip_canonical_sha256
            && row.11 == attachment.appearance_anchor_set_object_sha256
            && row.12 == attachment.appearance_anchor_set_canonical_sha256
    }) {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_SOCKET_BINDING_MISMATCH",
            "Attachment@3 AnimatedSocket@2 binding differs",
        ));
    }
    let projection: Option<HashMap<String, String>> = attachment_v3_parent_texts(
        connection,
        "game_weapon_animated_glb_socket_transform_projection_v2_links",
        "projection_key_sha256",
        &attachment.projection_key_sha256,
        &[
            "project_id",
            "appearance_candidate_id",
            "appearance_candidate_state_sha256",
            "appearance_delivery_manifest_object_sha256",
            "appearance_artifact_sha256",
            "animation_clip_id",
            "animation_clip_object_sha256",
            "animation_clip_canonical_sha256",
            "animated_artifact_sha256",
            "animation_receipt_object_sha256",
            "animation_receipt_canonical_sha256",
            "animated_socket_materialization_key_sha256",
            "anchor_set_object_sha256",
            "anchor_set_canonical_sha256",
            "projection_object_sha256",
            "canonical_sha256",
            "socket_node_id_encoding_sha256",
        ],
    )?;
    let Some(projection) = projection else {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_PROJECTION_BINDING_MISMATCH",
            "Attachment@3 Projection@2 parent is unavailable",
        ));
    };
    let projection_expected = [
        ("project_id", attachment.project_id.as_str()),
        (
            "appearance_candidate_id",
            attachment.appearance_candidate_id.as_str(),
        ),
        (
            "appearance_candidate_state_sha256",
            attachment.appearance_candidate_state_sha256.as_str(),
        ),
        (
            "appearance_delivery_manifest_object_sha256",
            attachment
                .appearance_delivery_manifest_object_sha256
                .as_str(),
        ),
        (
            "appearance_artifact_sha256",
            attachment.appearance_artifact_sha256.as_str(),
        ),
        ("animation_clip_id", attachment.animation_clip_id.as_str()),
        (
            "animation_clip_object_sha256",
            attachment.animation_clip_object_sha256.as_str(),
        ),
        (
            "animation_clip_canonical_sha256",
            attachment.animation_clip_canonical_sha256.as_str(),
        ),
        (
            "animated_artifact_sha256",
            attachment.animated_artifact_sha256.as_str(),
        ),
        (
            "animation_receipt_object_sha256",
            attachment.animation_receipt_object_sha256.as_str(),
        ),
        (
            "animation_receipt_canonical_sha256",
            attachment.animation_receipt_canonical_sha256.as_str(),
        ),
        (
            "animated_socket_materialization_key_sha256",
            attachment
                .animated_socket_materialization_key_sha256
                .as_str(),
        ),
        (
            "anchor_set_object_sha256",
            attachment.animated_socket_anchor_set_object_sha256.as_str(),
        ),
        (
            "anchor_set_canonical_sha256",
            attachment
                .animated_socket_anchor_set_canonical_sha256
                .as_str(),
        ),
        (
            "projection_object_sha256",
            attachment.projection_object_sha256.as_str(),
        ),
        (
            "canonical_sha256",
            attachment.projection_canonical_sha256.as_str(),
        ),
        (
            "socket_node_id_encoding_sha256",
            attachment.socket_node_id_encoding_sha256.as_str(),
        ),
    ];
    if projection_expected
        .iter()
        .any(|(field, expected)| projection.get(*field).map(String::as_str) != Some(*expected))
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_PROJECTION_BINDING_MISMATCH",
            "Attachment@3 Projection@2 field differs",
        ));
    }
    let common_fields = [
        "project_id",
        "geometry_candidate_id",
        "geometry_candidate_state_sha256",
        "geometry_delivery_manifest_object_sha256",
        "geometry_artifact_sha256",
        "appearance_candidate_id",
        "appearance_candidate_state_sha256",
        "appearance_delivery_manifest_object_sha256",
        "appearance_artifact_sha256",
        "material_surface_quality_id",
        "material_surface_quality_report_object_sha256",
        "material_surface_quality_canonical_sha256",
        "geometry_preservation_projection_sha256",
        "geometry_preservation_status",
        "projection_key_sha256",
        "projection_object_sha256",
        "projection_canonical_sha256",
        "animated_socket_materialization_key_sha256",
        "animated_artifact_sha256",
        "animated_socket_anchor_set_object_sha256",
        "animated_socket_anchor_set_canonical_sha256",
        "appearance_anchor_set_object_sha256",
        "appearance_anchor_set_canonical_sha256",
        "anchor_binding_policy",
        "anchor_binding_sha256",
        "animation_clip_id",
        "animation_clip_object_sha256",
        "animation_clip_canonical_sha256",
        "animation_receipt_object_sha256",
        "animation_receipt_canonical_sha256",
        "vfx_profile_object_sha256",
        "vfx_profile_canonical_sha256",
        "socket_node_id_encoding_sha256",
        "socket_roles_sha256",
        "camera_object_sha256",
        "camera_identity_sha256",
        "render_profile_sha256",
        "render_worker_build_cohort_sha256",
        "sample_schedule_sha256",
    ];
    for (label, table, key) in [
        (
            "Particles@2",
            "fictional_energy_vfx_animated_socket_particles_v2_projection_sequence_links",
            attachment.particle_sequence_key_sha256.as_str(),
        ),
        (
            "Trails@2",
            "fictional_energy_vfx_animated_socket_trails_v2_projection_sequence_links",
            attachment.trail_sequence_key_sha256.as_str(),
        ),
        (
            "TrailsBloom@2",
            "fictional_energy_vfx_animated_socket_trails_bloom_v2_projection_sequence_links",
            attachment.trail_bloom_sequence_key_sha256.as_str(),
        ),
    ] {
        let parent = attachment_v3_parent_texts(
            connection,
            table,
            "sequence_key_sha256",
            key,
            &common_fields,
        )?;
        let Some(parent) = parent else {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_SEQUENCE_BINDING_MISMATCH",
                &format!("Attachment@3 {label} parent is unavailable"),
            ));
        };
        attachment_v3_require_parent_fields(&parent, attachment, key, label)?;
        let expected_canonical = match label {
            "Particles@2" => attachment.particle_sequence_canonical_sha256.as_str(),
            "Trails@2" => attachment.trail_sequence_canonical_sha256.as_str(),
            _ => attachment.trail_bloom_sequence_canonical_sha256.as_str(),
        };
        if parent.get("canonical_sha256").map(String::as_str) != Some(expected_canonical) {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_SEQUENCE_BINDING_MISMATCH",
                &format!("Attachment@3 {label} canonical differs"),
            ));
        }
    }
    let bloom_profile: String = connection.query_row(
        "SELECT trail_bloom_profile_sha256 FROM fictional_energy_vfx_animated_socket_trails_bloom_v2_projection_sequence_links WHERE sequence_key_sha256 = ?1",
        params![attachment.trail_bloom_sequence_key_sha256],
        |row| row.get(0),
    )?;
    if bloom_profile != attachment.trail_bloom_profile_sha256 {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_BLOOM_PROFILE_MISMATCH",
            "Attachment@3 TrailsBloom@2 profile differs",
        ));
    }
    for frame in &attachment.frames {
        validate_fictional_energy_vfx_animated_socket_attachment_v3_frame_binding(
            connection, attachment, frame,
        )?;
    }
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_attachment_v3_frame_binding(
    connection: &Connection,
    attachment: &FictionalEnergyVfxAnimatedSocketAttachmentV3Record,
    frame: &FictionalEnergyVfxAnimatedSocketAttachmentV3FrameRecord,
) -> Result<(), StoreError> {
    let projection: Option<(u64, String, String, String, String)> = connection
        .query_row(
            "SELECT sample_time_ticks, socket_transform_inventory_sha256, socket_transform_readback_sha256, projection_frame_canonical_sha256, projection_key_sha256 FROM game_weapon_animated_glb_socket_transform_projection_v2_frames WHERE projection_key_sha256 = ?1 AND frame_index = ?2",
            params![attachment.projection_key_sha256, i64::try_from(frame.projection_frame_index).unwrap_or(i64::MAX)],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
        )
        .optional()?;
    if !projection.is_some_and(|row| {
        row.0 == frame.sample_time_ticks
            && row.1 == frame.projection_socket_transform_inventory_sha256
            && row.2 == frame.projection_socket_transform_readback_sha256
            && row.3 == frame.projection_frame_canonical_sha256
            && row.4 == attachment.projection_key_sha256
    }) {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_PROJECTION_FRAME_MISMATCH",
            "Attachment@3 projection frame binding differs",
        ));
    }
    let particle: Option<(u64, String, String, String, String, String)> = connection
        .query_row(
            "SELECT sample_time_ticks, projection_frame_canonical_sha256, projection_socket_transform_inventory_sha256, projection_socket_transform_readback_sha256, particle_sequence_key_sha256, canonical_sha256 FROM fictional_energy_vfx_animated_socket_particles_v2_projection_sequence_frames WHERE sequence_key_sha256 = ?1 AND frame_index = ?2",
            params![attachment.particle_sequence_key_sha256, i64::try_from(frame.particle_sequence_frame_index).unwrap_or(i64::MAX)],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?)),
        )
        .optional()?;
    if !particle.is_some_and(|row| {
        row.0 == frame.sample_time_ticks
            && row.1 == frame.projection_frame_canonical_sha256
            && row.2 == frame.projection_socket_transform_inventory_sha256
            && row.3 == frame.projection_socket_transform_readback_sha256
            && row.4 == frame.particle_sequence_key_sha256
            && row.5 == frame.particle_sequence_frame_canonical_sha256
    }) {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_PARTICLE_FRAME_MISMATCH",
            "Attachment@3 particle frame binding differs",
        ));
    }
    let trail: Option<(u64, String, u64, String, String, String, String, String, String, String, String, String, String, String, String)> = connection
        .query_row(
            "SELECT sample_time_ticks, trail_sequence_key_sha256, trail_frame_index, trail_frame_canonical_sha256, trail_key_sha256, trail_inventory_sha256, trail_id_encoding_sha256, emitter_binding_sha256, current_projection_frame_canonical_sha256, current_projection_socket_transform_inventory_sha256, current_projection_socket_transform_readback_sha256, base_frame_key_sha256, bloom_key_sha256, particle_sequence_key_sha256, current_particle_frame_canonical_sha256 FROM fictional_energy_vfx_animated_socket_trails_v2_projection_sequence_frames WHERE sequence_key_sha256 = ?1 AND frame_index = ?2",
            params![attachment.trail_sequence_key_sha256, i64::try_from(frame.trail_frame_index).unwrap_or(i64::MAX)],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?, row.get(9)?, row.get(10)?, row.get(11)?, row.get(12)?, row.get(13)?, row.get(14)?)),
        )
        .optional()?;
    if !trail.is_some_and(|row| {
        row.0 == frame.sample_time_ticks
            && row.1 == attachment.trail_sequence_key_sha256
            && row.2 == frame.trail_frame_index
            && row.3 == frame.trail_sequence_frame_canonical_sha256
            && row.4 == frame.trail_key_sha256
            && row.5 == frame.trail_inventory_sha256
            && row.6 == frame.trail_id_encoding_sha256
            && row.7 == frame.emitter_binding_sha256
            && row.8 == frame.projection_frame_canonical_sha256
            && row.9 == frame.projection_socket_transform_inventory_sha256
            && row.10 == frame.projection_socket_transform_readback_sha256
            && row.11 == frame.base_frame_key_sha256
            && row.12 == frame.bloom_key_sha256
            && row.13 == frame.particle_sequence_key_sha256
            && row.14 == frame.particle_sequence_frame_canonical_sha256
    }) {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_TRAIL_FRAME_MISMATCH",
            "Attachment@3 trail frame binding differs",
        ));
    }
    let bloom: Option<(u64, String, u64, String, String, String, String, String, String, String)> = connection
        .query_row(
            "SELECT sample_time_ticks, trail_sequence_key_sha256, trail_frame_index, trail_frame_canonical_sha256, trail_bloom_key_sha256, trail_bloom_seed_sha256, base_frame_key_sha256, bloom_key_sha256, trail_bloom_sequence_key_sha256, trail_bloom_sequence_frame_canonical_sha256 FROM fictional_energy_vfx_animated_socket_trails_bloom_v2_projection_sequence_frames WHERE sequence_key_sha256 = ?1 AND frame_index = ?2",
            params![attachment.trail_bloom_sequence_key_sha256, i64::try_from(frame.trail_bloom_frame_index).unwrap_or(i64::MAX)],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?, row.get(9)?)),
        )
        .optional()?;
    if !bloom.is_some_and(|row| {
        row.0 == frame.sample_time_ticks
            && row.1 == attachment.trail_sequence_key_sha256
            && row.2 == frame.trail_frame_index
            && row.3 == frame.trail_sequence_frame_canonical_sha256
            && row.4 == frame.trail_bloom_key_sha256
            && row.5 == frame.trail_bloom_seed_sha256
            && row.6 == frame.base_frame_key_sha256
            && row.7 == frame.bloom_key_sha256
            && row.8 == frame.trail_bloom_sequence_key_sha256
            && row.9 == frame.trail_bloom_sequence_frame_canonical_sha256
    }) {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_TRAILS_BLOOM_FRAME_MISMATCH",
            "Attachment@3 TrailsBloom@2 frame binding differs",
        ));
    }
    Ok(())
}

fn fictional_energy_vfx_animated_socket_attachment_v3_reachable_hashes(
    connection: &Connection,
    attachment: &FictionalEnergyVfxAnimatedSocketAttachmentV3Record,
) -> Result<Vec<String>, StoreError> {
    let mut hashes = vec![
        attachment.geometry_delivery_manifest_object_sha256.clone(),
        attachment.geometry_artifact_sha256.clone(),
        attachment
            .appearance_delivery_manifest_object_sha256
            .clone(),
        attachment.appearance_artifact_sha256.clone(),
        attachment
            .material_surface_quality_report_object_sha256
            .clone(),
        attachment.animated_artifact_sha256.clone(),
        attachment.animated_socket_anchor_set_object_sha256.clone(),
        attachment.appearance_anchor_set_object_sha256.clone(),
        attachment.animation_clip_object_sha256.clone(),
        attachment.animation_receipt_object_sha256.clone(),
        attachment.projection_object_sha256.clone(),
        attachment.vfx_profile_object_sha256.clone(),
        attachment.camera_object_sha256.clone(),
        attachment.attachment_receipt_object_sha256.clone(),
    ];
    let mut extend_parent_objects = |table: &str, key: &str| -> Result<(), StoreError> {
        let fields = ["sequence_receipt_object_sha256"];
        if let Some(row) =
            attachment_v3_parent_texts(connection, table, "sequence_key_sha256", key, &fields)?
        {
            if let Some(hash) = row.get(fields[0]) {
                hashes.push(hash.clone());
            }
        }
        Ok(())
    };
    extend_parent_objects(
        "fictional_energy_vfx_animated_socket_particles_v2_projection_sequence_links",
        &attachment.particle_sequence_key_sha256,
    )?;
    extend_parent_objects(
        "fictional_energy_vfx_animated_socket_trails_v2_projection_sequence_links",
        &attachment.trail_sequence_key_sha256,
    )?;
    extend_parent_objects(
        "fictional_energy_vfx_animated_socket_trails_bloom_v2_projection_sequence_links",
        &attachment.trail_bloom_sequence_key_sha256,
    )?;
    for frame in &attachment.frames {
        for (table, key, index, fields) in [
            (
                "fictional_energy_vfx_animated_socket_particles_v2_projection_sequence_frames",
                attachment.particle_sequence_key_sha256.as_str(),
                frame.particle_sequence_frame_index,
                [
                    "render_set_object_sha256",
                    "receipt_object_sha256",
                    "particle_color_object_sha256",
                    "particle_id_object_sha256",
                    "particle_depth_object_sha256",
                ]
                .as_slice(),
            ),
            (
                "fictional_energy_vfx_animated_socket_trails_v2_projection_sequence_frames",
                attachment.trail_sequence_key_sha256.as_str(),
                frame.trail_frame_index,
                [
                    "render_set_object_sha256",
                    "receipt_object_sha256",
                    "trail_color_object_sha256",
                    "trail_id_object_sha256",
                    "trail_depth_object_sha256",
                ]
                .as_slice(),
            ),
            (
                "fictional_energy_vfx_animated_socket_trails_bloom_v2_projection_sequence_frames",
                attachment.trail_bloom_sequence_key_sha256.as_str(),
                frame.trail_bloom_frame_index,
                [
                    "base_opaque_depth_object_sha256",
                    "trail_emissive_source_object_sha256",
                    "trail_bloom_contribution_object_sha256",
                    "render_set_object_sha256",
                    "receipt_object_sha256",
                ]
                .as_slice(),
            ),
        ] {
            let sql = format!(
                "SELECT {} FROM {} WHERE sequence_key_sha256 = ?1 AND frame_index = ?2",
                fields.join(", "),
                table
            );
            let values: Option<Vec<String>> = connection
                .query_row(
                    &sql,
                    params![key, i64::try_from(index).unwrap_or(i64::MAX)],
                    |row| (0..fields.len()).map(|i| row.get(i)).collect(),
                )
                .optional()?;
            if let Some(values) = values {
                hashes.extend(values);
            }
        }
    }
    hashes.sort();
    hashes.dedup();
    if hashes.len() > MAX_JOB_REACHABILITY_HASHES {
        return Err(StoreError::InvalidData(
            "Attachment@3 reachability set exceeds its bound".to_owned(),
        ));
    }
    Ok(hashes)
}

fn validate_fictional_energy_vfx_animated_socket_attachment_v2_binding_in_transaction(
    connection: &Connection,
    attachment: &FictionalEnergyVfxAnimatedSocketAttachmentV2Record,
) -> Result<(), StoreError> {
    let key_is_cas: i64 = connection.query_row(
        "SELECT COUNT(*) FROM objects WHERE sha256 = ?1",
        params![attachment.attachment_key_sha256],
        |row| row.get(0),
    )?;
    if key_is_cas != 0 {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_KEY_IS_CAS".to_owned(),
            message: "animated socket attachment V2 lookup key must not be a CAS object".to_owned(),
        });
    }
    let delivery_matches: i64 = connection.query_row(
        "SELECT COUNT(*) FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1 AND project_id = ?2 AND lod0_candidate_id = ?3 AND lod0_artifact_sha256 = ?4",
        params![
            attachment.delivery_manifest_object_sha256,
            attachment.project_id,
            attachment.candidate_id,
            attachment.source_artifact_sha256,
        ],
        |row| row.get(0),
    )?;
    let candidate_matches: i64 = connection.query_row(
        "SELECT COUNT(*) FROM candidates WHERE candidate_id = ?1 AND project_id = ?2 AND canonical_sha256 = ?3 AND prepared_object_sha256 = ?4 AND manifest_hash = ?4",
        params![
            attachment.candidate_id,
            attachment.project_id,
            attachment.candidate_state_sha256,
            attachment.source_artifact_sha256,
        ],
        |row| row.get(0),
    )?;
    if delivery_matches != 1 || candidate_matches != 1 {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_SOURCE_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket attachment V2 delivery/candidate/artifact binding differs"
                .to_owned(),
        });
    }

    let socket_matches: i64 = connection.query_row(
        "SELECT COUNT(*) FROM game_weapon_animated_glb_socket_materialization_links WHERE animated_socket_materialization_key_sha256 = ?1 AND project_id = ?2 AND candidate_id = ?3 AND candidate_state_sha256 = ?4 AND delivery_manifest_object_sha256 = ?5 AND source_artifact_sha256 = ?6 AND animated_artifact_sha256 = ?7 AND animation_receipt_object_sha256 = ?8 AND animation_receipt_canonical_sha256 = ?9 AND anchor_set_object_sha256 = ?10 AND anchor_set_canonical_sha256 = ?11 AND socket_node_id_encoding_sha256 = ?12 AND lod_scope = 'lod0-animated-source-only@1'",
        params![
            attachment.animated_socket_materialization_key_sha256,
            attachment.project_id,
            attachment.candidate_id,
            attachment.candidate_state_sha256,
            attachment.delivery_manifest_object_sha256,
            attachment.source_artifact_sha256,
            attachment.animated_artifact_sha256,
            attachment.animation_receipt_object_sha256,
            attachment.animation_receipt_canonical_sha256,
            attachment.animated_socket_anchor_set_object_sha256,
            attachment.animated_socket_anchor_set_canonical_sha256,
            attachment.socket_node_id_encoding_sha256,
        ],
        |row| row.get(0),
    )?;
    let clip_matches: i64 = connection.query_row(
        "SELECT COUNT(*) FROM mechanical_animation_clip_links WHERE project_id = ?1 AND candidate_id = ?2 AND artifact_id = ?3 AND clip_id = ?4 AND clip_object_sha256 = ?5 AND clip_sha256 = ?6",
        params![
            attachment.project_id,
            attachment.candidate_id,
            attachment.source_artifact_sha256,
            attachment.animation_clip_id,
            attachment.animation_clip_object_sha256,
            attachment.animation_clip_canonical_sha256,
        ],
        |row| row.get(0),
    )?;
    let profile_matches: i64 = connection.query_row(
        "SELECT COUNT(*) FROM fictional_energy_vfx_links WHERE project_id = ?1 AND delivery_manifest_object_sha256 = ?2 AND anchor_set_object_sha256 = ?3 AND vfx_profile_object_sha256 = ?4",
        params![
            attachment.project_id,
            attachment.delivery_manifest_object_sha256,
            attachment.animated_socket_anchor_set_object_sha256,
            attachment.vfx_profile_object_sha256,
        ],
        |row| row.get(0),
    )?;
    if socket_matches != 1 || clip_matches != 1 || profile_matches != 1 {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_ANIMATION_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket attachment V2 socket/clip/profile binding differs".to_owned(),
        });
    }

    let projection_matches: i64 = connection.query_row(
        "SELECT COUNT(*) FROM game_weapon_animated_glb_socket_transform_projection_links WHERE projection_key_sha256 = ?1 AND project_id = ?2 AND candidate_id = ?3 AND candidate_state_sha256 = ?4 AND delivery_manifest_object_sha256 = ?5 AND source_artifact_sha256 = ?6 AND animated_artifact_sha256 = ?7 AND animation_receipt_object_sha256 = ?8 AND animation_receipt_canonical_sha256 = ?9 AND animated_socket_materialization_key_sha256 = ?10 AND anchor_set_object_sha256 = ?11 AND anchor_set_canonical_sha256 = ?12 AND animation_clip_id = ?13 AND animation_clip_object_sha256 = ?14 AND animation_clip_canonical_sha256 = ?15 AND socket_node_id_encoding_sha256 = ?16 AND socket_roles_sha256 = ?17 AND projection_object_sha256 = ?18 AND canonical_sha256 = ?19",
        params![
            attachment.projection_key_sha256,
            attachment.project_id,
            attachment.candidate_id,
            attachment.candidate_state_sha256,
            attachment.delivery_manifest_object_sha256,
            attachment.source_artifact_sha256,
            attachment.animated_artifact_sha256,
            attachment.animation_receipt_object_sha256,
            attachment.animation_receipt_canonical_sha256,
            attachment.animated_socket_materialization_key_sha256,
            attachment.animated_socket_anchor_set_object_sha256,
            attachment.animated_socket_anchor_set_canonical_sha256,
            attachment.animation_clip_id,
            attachment.animation_clip_object_sha256,
            attachment.animation_clip_canonical_sha256,
            attachment.socket_node_id_encoding_sha256,
            attachment.socket_roles_sha256,
            attachment.projection_object_sha256,
            attachment.projection_canonical_sha256,
        ],
        |row| row.get(0),
    )?;
    if projection_matches != 1 {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_PROJECTION_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket attachment V2 projection binding differs".to_owned(),
        });
    }

    let common_sequence_matches = |table: &str,
                                   key: &str,
                                   canonical_sha256: &str|
     -> Result<bool, StoreError> {
        if !matches!(
            table,
            "fictional_energy_vfx_animated_socket_particles_sequence_links"
                | "fictional_energy_vfx_animated_socket_trails_sequence_links"
                | "fictional_energy_vfx_animated_socket_trails_bloom_sequence_links"
        ) {
            return Ok(false);
        }
        let sql = format!(
            "SELECT COUNT(*) FROM {table} WHERE sequence_key_sha256 = ?1 AND project_id = ?2 AND candidate_id = ?3 AND candidate_state_sha256 = ?4 AND delivery_manifest_object_sha256 = ?5 AND source_artifact_sha256 = ?6 AND projection_key_sha256 = ?7 AND projection_object_sha256 = ?8 AND projection_canonical_sha256 = ?9 AND animated_socket_materialization_key_sha256 = ?10 AND animated_artifact_sha256 = ?11 AND animated_socket_anchor_set_object_sha256 = ?12 AND animated_socket_anchor_set_canonical_sha256 = ?13 AND animation_clip_id = ?14 AND animation_clip_object_sha256 = ?15 AND animation_clip_canonical_sha256 = ?16 AND animation_receipt_object_sha256 = ?17 AND animation_receipt_canonical_sha256 = ?18 AND vfx_profile_object_sha256 = ?19 AND vfx_profile_canonical_sha256 = ?20 AND socket_node_id_encoding_sha256 = ?21 AND socket_roles_sha256 = ?22 AND canonical_sha256 = ?23"
        );
        let count: i64 = connection.query_row(
            &sql,
            params![
                key,
                attachment.project_id,
                attachment.candidate_id,
                attachment.candidate_state_sha256,
                attachment.delivery_manifest_object_sha256,
                attachment.source_artifact_sha256,
                attachment.projection_key_sha256,
                attachment.projection_object_sha256,
                attachment.projection_canonical_sha256,
                attachment.animated_socket_materialization_key_sha256,
                attachment.animated_artifact_sha256,
                attachment.animated_socket_anchor_set_object_sha256,
                attachment.animated_socket_anchor_set_canonical_sha256,
                attachment.animation_clip_id,
                attachment.animation_clip_object_sha256,
                attachment.animation_clip_canonical_sha256,
                attachment.animation_receipt_object_sha256,
                attachment.animation_receipt_canonical_sha256,
                attachment.vfx_profile_object_sha256,
                attachment.vfx_profile_canonical_sha256,
                attachment.socket_node_id_encoding_sha256,
                attachment.socket_roles_sha256,
                canonical_sha256,
            ],
            |row| row.get(0),
        )?;
        Ok(count == 1)
    };
    if !common_sequence_matches(
        "fictional_energy_vfx_animated_socket_particles_sequence_links",
        &attachment.particle_sequence_key_sha256,
        &attachment.particle_sequence_canonical_sha256,
    )? || !common_sequence_matches(
        "fictional_energy_vfx_animated_socket_trails_sequence_links",
        &attachment.trail_sequence_key_sha256,
        &attachment.trail_sequence_canonical_sha256,
    )? || !common_sequence_matches(
        "fictional_energy_vfx_animated_socket_trails_bloom_sequence_links",
        &attachment.trail_bloom_sequence_key_sha256,
        &attachment.trail_bloom_sequence_canonical_sha256,
    )? {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_SEQUENCE_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket attachment V2 sequence binding differs".to_owned(),
        });
    }
    let trail_bloom_source_matches: i64 = connection.query_row(
        "SELECT COUNT(*) FROM fictional_energy_vfx_animated_socket_trails_bloom_sequence_links WHERE sequence_key_sha256 = ?1 AND trail_sequence_key_sha256 = ?2 AND trail_sequence_canonical_sha256 = ?3",
        params![
            attachment.trail_bloom_sequence_key_sha256,
            attachment.trail_sequence_key_sha256,
            attachment.trail_sequence_canonical_sha256,
        ],
        |row| row.get(0),
    )?;
    if trail_bloom_source_matches != 1 {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_TRAIL_BLOOM_SOURCE_MISMATCH"
                .to_owned(),
            message: "animated socket attachment V2 trail Bloom source sequence differs".to_owned(),
        });
    }

    for frame in &attachment.frames {
        validate_fictional_energy_vfx_animated_socket_attachment_v2_frame_binding(
            connection, attachment, frame,
        )?;
    }
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_attachment_v2_frame_binding(
    connection: &Connection,
    attachment: &FictionalEnergyVfxAnimatedSocketAttachmentV2Record,
    frame: &FictionalEnergyVfxAnimatedSocketAttachmentV2FrameRecord,
) -> Result<(), StoreError> {
    type TrailFrameRow = (
        u64,
        u64,
        u64,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
    );
    let trail: Option<TrailFrameRow> = connection
        .query_row(
            "SELECT sample_time_ticks, current_projection_frame_index, current_particle_frame_index, current_particle_key_sha256, current_particle_frame_canonical_sha256, current_projection_frame_canonical_sha256, current_projection_socket_transform_inventory_sha256, current_projection_socket_transform_readback_sha256, particle_sequence_key_sha256, base_frame_key_sha256, bloom_key_sha256, emitter_binding_sha256, trail_key_sha256, canonical_sha256 FROM fictional_energy_vfx_animated_socket_trails_sequence_frames WHERE sequence_key_sha256 = ?1 AND frame_index = ?2",
            params![
                attachment.trail_sequence_key_sha256,
                i64::try_from(frame.frame_index).unwrap_or(i64::MAX),
            ],
            |row| {
                Ok((
                    row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?,
                    row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?, row.get(9)?,
                    row.get(10)?, row.get(11)?, row.get(12)?, row.get(13)?,
                ))
            },
        )
        .optional()?;
    let Some(trail) = trail else {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_TRAIL_FRAME_MISMATCH"
                .to_owned(),
            message: "animated socket attachment V2 trail frame is unavailable".to_owned(),
        });
    };
    if trail.1 != frame.projection_frame_index
        || trail.2 != frame.particle_sequence_frame_index
        || trail.1 != frame.frame_index + 1
        || trail.2 != frame.frame_index + 1
        || trail.8 != attachment.particle_sequence_key_sha256
        || trail.0 != frame.sample_time_ticks
        || trail.3 != frame.particle_key_sha256
        || trail.4 != frame.particle_sequence_frame_canonical_sha256
        || trail.5 != frame.projection_frame_canonical_sha256
        || trail.6 != frame.socket_transform_inventory_sha256
        || trail.7 != frame.socket_transform_readback_sha256
        || trail.9 != frame.base_frame_key_sha256
        || trail.10 != frame.bloom_key_sha256
        || trail.11 != frame.trail_socket_bindings_sha256
        || trail.12 != frame.trail_key_sha256
        || trail.13 != frame.trail_sequence_frame_canonical_sha256
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_TRAIL_FRAME_MISMATCH"
                .to_owned(),
            message: "animated socket attachment V2 trail frame binding differs".to_owned(),
        });
    }

    let projection: Option<(u64, String, String, String, String)> = connection
        .query_row(
            "SELECT sample_time_ticks, source_animation_sample_sha256, socket_transform_inventory_sha256, socket_transform_readback_sha256, canonical_sha256 FROM game_weapon_animated_glb_socket_transform_projection_frames WHERE projection_key_sha256 = ?1 AND frame_index = ?2",
            params![
                attachment.projection_key_sha256,
                i64::try_from(frame.projection_frame_index).unwrap_or(i64::MAX),
            ],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
        )
        .optional()?;
    if !projection.is_some_and(|row| {
        row.0 == frame.sample_time_ticks
            && row.1 == frame.animation_pose_readback_sha256
            && row.2 == frame.socket_transform_inventory_sha256
            && row.3 == frame.socket_transform_readback_sha256
            && row.4 == frame.projection_frame_canonical_sha256
    }) {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_PROJECTION_FRAME_MISMATCH"
                .to_owned(),
            message: "animated socket attachment V2 projection frame binding differs".to_owned(),
        });
    }

    type ParticleFrameRow = (
        u64,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
    );
    let particle: Option<ParticleFrameRow> = connection
        .query_row(
            "SELECT sample_time_ticks, projection_frame_canonical_sha256, projection_socket_transform_inventory_sha256, projection_socket_transform_readback_sha256, base_frame_key_sha256, bloom_key_sha256, emitter_socket_bindings_sha256, particle_key_sha256, canonical_sha256 FROM fictional_energy_vfx_animated_socket_particles_sequence_frames WHERE sequence_key_sha256 = ?1 AND frame_index = ?2",
            params![
                attachment.particle_sequence_key_sha256,
                i64::try_from(frame.particle_sequence_frame_index).unwrap_or(i64::MAX),
            ],
            |row| {
                Ok((
                    row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?,
                    row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?,
                ))
            },
        )
        .optional()?;
    if !particle.is_some_and(|row| {
        row.0 == frame.sample_time_ticks
            && row.1 == frame.projection_frame_canonical_sha256
            && row.2 == frame.socket_transform_inventory_sha256
            && row.3 == frame.socket_transform_readback_sha256
            && row.4 == frame.base_frame_key_sha256
            && row.5 == frame.bloom_key_sha256
            && row.6 == frame.emitter_socket_bindings_sha256
            && row.7 == frame.particle_key_sha256
            && row.8 == frame.particle_sequence_frame_canonical_sha256
    }) {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_PARTICLE_FRAME_MISMATCH"
                .to_owned(),
            message: "animated socket attachment V2 particle frame binding differs".to_owned(),
        });
    }

    type TrailBloomFrameRow = (
        u64,
        String,
        u64,
        String,
        String,
        String,
        String,
        String,
        String,
    );
    let trail_bloom: Option<TrailBloomFrameRow> = connection
        .query_row(
            "SELECT sample_time_ticks, trail_sequence_key_sha256, trail_frame_index, trail_frame_canonical_sha256, particle_sequence_frame_canonical_sha256, base_frame_key_sha256, bloom_key_sha256, trail_bloom_key_sha256, canonical_sha256 FROM fictional_energy_vfx_animated_socket_trails_bloom_sequence_frames WHERE sequence_key_sha256 = ?1 AND frame_index = ?2",
            params![
                attachment.trail_bloom_sequence_key_sha256,
                i64::try_from(frame.frame_index).unwrap_or(i64::MAX),
            ],
            |row| {
                Ok((
                    row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?,
                    row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?,
                ))
            },
        )
        .optional()?;
    if !trail_bloom.is_some_and(|row| {
        row.0 == frame.sample_time_ticks
            && row.1 == attachment.trail_sequence_key_sha256
            && row.2 == frame.frame_index
            && row.3 == frame.trail_sequence_frame_canonical_sha256
            && row.4 == frame.particle_sequence_frame_canonical_sha256
            && row.5 == frame.base_frame_key_sha256
            && row.6 == frame.bloom_key_sha256
            && row.7 == frame.trail_bloom_key_sha256
            && row.8 == frame.trail_bloom_sequence_frame_canonical_sha256
    }) {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_TRAIL_BLOOM_FRAME_MISMATCH"
                .to_owned(),
            message: "animated socket attachment V2 trail Bloom frame binding differs".to_owned(),
        });
    }

    let render_context: Option<(
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
    )> = connection
        .query_row(
            "SELECT p.camera_object_sha256, p.camera_identity_sha256, p.render_profile_sha256, p.render_worker_build_cohort_sha256, t.camera_object_sha256, t.camera_identity_sha256, t.render_profile_sha256, t.render_worker_build_cohort_sha256, b.camera_object_sha256 || ':' || b.camera_identity_sha256 || ':' || b.render_profile_sha256 || ':' || b.render_worker_build_cohort_sha256 FROM fictional_energy_vfx_animated_socket_particles_sequence_links p JOIN fictional_energy_vfx_animated_socket_trails_sequence_links t ON t.sequence_key_sha256 = ?2 JOIN fictional_energy_vfx_animated_socket_trails_bloom_sequence_links b ON b.sequence_key_sha256 = ?3 WHERE p.sequence_key_sha256 = ?1",
            params![
                attachment.particle_sequence_key_sha256,
                attachment.trail_sequence_key_sha256,
                attachment.trail_bloom_sequence_key_sha256,
            ],
            |row| {
                Ok((
                    row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?,
                    row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?,
                ))
            },
        )
        .optional()?;
    if !render_context.is_some_and(|row| {
        row.0 == row.4
            && row.1 == row.5
            && row.2 == row.6
            && row.3 == row.7
            && row.8 == format!("{}:{}:{}:{}", row.0, row.1, row.2, row.3)
    }) {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_RENDER_CONTEXT_MISMATCH"
                .to_owned(),
            message: "animated socket attachment V2 camera/render cohort differs".to_owned(),
        });
    }
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_attachment_binding_in_transaction(
    connection: &Connection,
    attachment: &FictionalEnergyVfxAnimatedSocketAttachmentRecord,
) -> Result<(), StoreError> {
    let delivery: Option<(String, String, String)> = connection
        .query_row(
            "SELECT project_id, lod0_candidate_id, lod0_artifact_sha256 FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1",
            params![attachment.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if delivery.as_ref().map(|row| row.0.as_str()) != Some(attachment.project_id.as_str())
        || delivery.as_ref().map(|row| row.1.as_str()) != Some(attachment.candidate_id.as_str())
        || delivery.as_ref().map(|row| row.2.as_str())
            != Some(attachment.source_artifact_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_DELIVERY_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket attachment delivery/candidate/artifact binding differs"
                .to_owned(),
        });
    }
    let candidate: Option<(String, String, Option<String>, Option<String>)> = connection
        .query_row(
            "SELECT project_id, canonical_sha256, prepared_object_sha256, manifest_hash FROM candidates WHERE candidate_id = ?1",
            params![attachment.candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if candidate.as_ref().map(|row| row.0.as_str()) != Some(attachment.project_id.as_str())
        || candidate.as_ref().map(|row| row.1.as_str())
            != Some(attachment.candidate_state_sha256.as_str())
        || candidate.as_ref().and_then(|row| row.2.as_deref())
            != Some(attachment.source_artifact_sha256.as_str())
        || candidate.as_ref().and_then(|row| row.3.as_deref())
            != Some(attachment.source_artifact_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_CANDIDATE_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket attachment candidate/state/artifact binding differs"
                .to_owned(),
        });
    }
    let animated_socket: Option<(
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
    )> = connection
        .query_row(
            "SELECT project_id, candidate_id, candidate_state_sha256, delivery_manifest_object_sha256, source_artifact_sha256, animated_artifact_sha256, animation_receipt_object_sha256, animation_receipt_canonical_sha256, anchor_set_object_sha256, anchor_set_canonical_sha256, derived_animated_socket_artifact_sha256, receipt_object_sha256, animated_socket_materialization_key_sha256, lod_scope FROM game_weapon_animated_glb_socket_materialization_links WHERE animated_socket_materialization_key_sha256 = ?1",
            params![attachment.animated_socket_materialization_key_sha256],
            |row| {
                Ok((
                    row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?,
                    row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?, row.get(9)?,
                    row.get(10)?, row.get(11)?, row.get(12)?, row.get(13)?,
                ))
            },
        )
        .optional()?;
    let Some(animated_socket) = animated_socket else {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_SOCKET_NOT_FOUND".to_owned(),
            message: "animated socket materialization link is unavailable".to_owned(),
        });
    };
    if animated_socket.0 != attachment.project_id
        || animated_socket.1 != attachment.candidate_id
        || animated_socket.2 != attachment.candidate_state_sha256
        || animated_socket.3 != attachment.delivery_manifest_object_sha256
        || animated_socket.4 != attachment.source_artifact_sha256
        || animated_socket.5 != attachment.animated_artifact_sha256
        || animated_socket.6 != attachment.animation_receipt_object_sha256
        || animated_socket.7 != attachment.animation_receipt_canonical_sha256
        || animated_socket.8 != attachment.animated_socket_anchor_set_object_sha256
        || animated_socket.9 != attachment.animated_socket_anchor_set_canonical_sha256
        || animated_socket.13 != "lod0-animated-source-only@1"
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_SOCKET_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket source/derived/AnchorSet binding differs".to_owned(),
        });
    }
    let clip: Option<(String, String, String, String, String)> = connection
        .query_row(
            "SELECT project_id, candidate_id, artifact_id, clip_object_sha256, clip_sha256 FROM mechanical_animation_clip_links WHERE candidate_id = ?1 AND clip_id = ?2",
            params![attachment.candidate_id, attachment.animation_clip_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
        )
        .optional()?;
    if clip.as_ref().map(|row| row.0.as_str()) != Some(attachment.project_id.as_str())
        || clip.as_ref().map(|row| row.1.as_str()) != Some(attachment.candidate_id.as_str())
        || clip.as_ref().map(|row| row.2.as_str())
            != Some(attachment.source_artifact_sha256.as_str())
        || clip.as_ref().map(|row| row.3.as_str())
            != Some(attachment.animation_clip_object_sha256.as_str())
        || clip.as_ref().map(|row| row.4.as_str())
            != Some(attachment.animation_clip_canonical_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_CLIP_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket attachment animation clip binding differs".to_owned(),
        });
    }
    let profile: Option<(String, String, String)> = connection
        .query_row(
            "SELECT project_id, vfx_profile_object_sha256, anchor_set_object_sha256 FROM fictional_energy_vfx_links WHERE delivery_manifest_object_sha256 = ?1",
            params![attachment.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if profile.as_ref().map(|row| row.0.as_str()) != Some(attachment.project_id.as_str())
        || profile.as_ref().map(|row| row.1.as_str())
            != Some(attachment.vfx_profile_object_sha256.as_str())
        || profile.as_ref().map(|row| row.2.as_str())
            != Some(attachment.animated_socket_anchor_set_object_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_PROFILE_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket attachment VFX profile/AnchorSet binding differs".to_owned(),
        });
    }
    let sequence: Option<(String, String, String, String, String, String)> = connection
        .query_row(
            "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, source_candidate_id, source_artifact_sha256, canonical_sha256 FROM fictional_energy_vfx_sequence_links WHERE sequence_key_sha256 = ?1",
            params![attachment.vfx_sequence_key_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?)),
        )
        .optional()?;
    if sequence.as_ref().map(|row| row.0.as_str()) != Some(attachment.project_id.as_str())
        || sequence.as_ref().map(|row| row.1.as_str())
            != Some(attachment.delivery_manifest_object_sha256.as_str())
        || sequence.as_ref().map(|row| row.2.as_str())
            != Some(attachment.vfx_profile_object_sha256.as_str())
        || sequence.as_ref().map(|row| row.3.as_str()) != Some(attachment.candidate_id.as_str())
        || sequence.as_ref().map(|row| row.4.as_str())
            != Some(attachment.source_artifact_sha256.as_str())
        || sequence.as_ref().map(|row| row.5.as_str())
            != Some(attachment.vfx_sequence_canonical_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_SEQUENCE_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket attachment VFX sequence binding differs".to_owned(),
        });
    }
    for frame in &attachment.frames {
        validate_fictional_energy_vfx_animated_socket_attachment_frame_binding(
            connection, attachment, frame,
        )?;
    }
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_attachment_frame_binding(
    connection: &Connection,
    attachment: &FictionalEnergyVfxAnimatedSocketAttachmentRecord,
    frame: &FictionalEnergyVfxAnimatedSocketAttachmentFrameRecord,
) -> Result<(), StoreError> {
    let base: Option<(String, String, String, String, String)> = connection
        .query_row(
            "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, source_candidate_id, source_artifact_sha256 FROM fictional_energy_vfx_frame_links WHERE frame_key_sha256 = ?1",
            params![frame.base_frame_key_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
        )
        .optional()?;
    let bloom: Option<(String, String, String, String, String, String)> = connection
        .query_row(
            "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, source_candidate_id, source_artifact_sha256, base_frame_key_sha256 FROM fictional_energy_vfx_bloom_frame_links WHERE bloom_key_sha256 = ?1",
            params![frame.bloom_key_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?)),
        )
        .optional()?;
    let particle: Option<(String, String, String, String, String, String, String, String)> = connection
        .query_row(
            "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, anchor_set_object_sha256, source_candidate_id, source_artifact_sha256, base_frame_key_sha256, bloom_key_sha256 FROM fictional_energy_vfx_particles_frame_links WHERE particle_key_sha256 = ?1",
            params![frame.particle_key_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?)),
        )
        .optional()?;
    let trail: Option<(String, String, String, String, String, String, String, String, String)> = connection
        .query_row(
            "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, anchor_set_object_sha256, source_candidate_id, source_artifact_sha256, base_frame_key_sha256, bloom_key_sha256, current_particle_key_sha256 FROM fictional_energy_vfx_trails_frame_links WHERE trail_key_sha256 = ?1",
            params![frame.trail_key_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?)),
        )
        .optional()?;
    let trail_bloom: Option<(
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
    )> = connection
        .query_row(
            "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, anchor_set_object_sha256, source_candidate_id, source_artifact_sha256, base_frame_key_sha256, bloom_key_sha256, source_trail_key_sha256 FROM fictional_energy_vfx_trails_bloom_frame_links WHERE trail_bloom_key_sha256 = ?1",
            params![frame.trail_bloom_key_sha256],
            |row| {
                Ok((
                    row.get(0)?,
                    row.get(1)?,
                    row.get(2)?,
                    row.get(3)?,
                    row.get(4)?,
                    row.get(5)?,
                    row.get(6)?,
                    row.get(7)?,
                    row.get(8)?,
                ))
            },
        )
        .optional()?;
    let context_matches =
        |project: &str, delivery: &str, profile: &str, candidate: &str, artifact: &str| -> bool {
            project == attachment.project_id
                && delivery == attachment.delivery_manifest_object_sha256
                && profile == attachment.vfx_profile_object_sha256
                && candidate == attachment.candidate_id
                && artifact == attachment.source_artifact_sha256
        };
    if !base
        .as_ref()
        .is_some_and(|row| context_matches(&row.0, &row.1, &row.2, &row.3, &row.4))
        || !bloom.as_ref().is_some_and(|row| {
            context_matches(&row.0, &row.1, &row.2, &row.3, &row.4)
                && row.5 == frame.base_frame_key_sha256
        })
        || !particle.as_ref().is_some_and(|row| {
            context_matches(&row.0, &row.1, &row.2, &row.4, &row.5)
                && row.3 == attachment.animated_socket_anchor_set_object_sha256
                && row.6 == frame.base_frame_key_sha256
                && row.7 == frame.bloom_key_sha256
        })
        || !trail.as_ref().is_some_and(|row| {
            context_matches(&row.0, &row.1, &row.2, &row.4, &row.5)
                && row.3 == attachment.animated_socket_anchor_set_object_sha256
                && row.6 == frame.base_frame_key_sha256
                && row.7 == frame.bloom_key_sha256
                && row.8 == frame.particle_key_sha256
        })
        || !trail_bloom.as_ref().is_some_and(|row| {
            context_matches(&row.0, &row.1, &row.2, &row.4, &row.5)
                && row.3 == attachment.animated_socket_anchor_set_object_sha256
                && row.6 == frame.base_frame_key_sha256
                && row.7 == frame.bloom_key_sha256
        })
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_FRAME_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket attachment frame does not bind to the exact VFX stack"
                .to_owned(),
        });
    }
    if !trail_bloom
        .as_ref()
        .is_some_and(|row| row.8 == frame.trail_key_sha256)
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_TRAIL_BLOOM_SOURCE_TRAIL_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket attachment trail bloom is bound to a different trail"
                .to_owned(),
        });
    }
    Ok(())
}

fn validate_fictional_energy_vfx_sequence_link(
    link: &FictionalEnergyVfxSequenceLinkRecord,
) -> Result<(), StoreError> {
    let mut canonical = link.clone();
    canonical.canonical_sha256.clear();
    let expected = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    if link.schema_version != "FictionalEnergyVfxSequenceLink@1"
        || !is_sha256(&link.sequence_key_sha256)
        || !is_opaque_id(&link.project_id)
        || !is_sha256(&link.delivery_manifest_object_sha256)
        || !is_sha256(&link.vfx_profile_object_sha256)
        || !is_opaque_id(&link.source_candidate_id)
        || !is_sha256(&link.source_artifact_sha256)
        || !is_sha256(&link.request_sha256)
        || !is_sha256(&link.camera_object_sha256)
        || !is_sha256(&link.camera_identity_sha256)
        || !is_sha256(&link.render_profile_sha256)
        || !is_sha256(&link.render_worker_build_cohort_sha256)
        || !is_sha256(&link.receipt_object_sha256)
        || !(2..=16).contains(&link.frame_key_sha256s.len())
        || link.frame_key_sha256s.iter().any(|value| !is_sha256(value))
        || link.materialization_status
            != "runtime-owned-durable-fictional-energy-vfx-rendered-sequence"
        || link.canonical_sha256 != expected
        || link.created_at.is_empty()
        || link.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "fictional energy VFX sequence link is malformed".to_owned(),
        ));
    }
    Ok(())
}

fn fictional_energy_vfx_sequence_link_from_row(
    row: &rusqlite::Row<'_>,
) -> rusqlite::Result<FictionalEnergyVfxSequenceLinkRecord> {
    let frame_key_sha256s_json: String = row.get(12)?;
    let frame_key_sha256s = serde_json::from_str(&frame_key_sha256s_json).map_err(|error| {
        rusqlite::Error::FromSqlConversionFailure(12, rusqlite::types::Type::Text, Box::new(error))
    })?;
    Ok(FictionalEnergyVfxSequenceLinkRecord {
        schema_version: "FictionalEnergyVfxSequenceLink@1".to_owned(),
        sequence_key_sha256: row.get(0)?,
        project_id: row.get(1)?,
        delivery_manifest_object_sha256: row.get(2)?,
        vfx_profile_object_sha256: row.get(3)?,
        source_candidate_id: row.get(4)?,
        source_artifact_sha256: row.get(5)?,
        request_sha256: row.get(6)?,
        camera_object_sha256: row.get(7)?,
        camera_identity_sha256: row.get(8)?,
        render_profile_sha256: row.get(9)?,
        render_worker_build_cohort_sha256: row.get(10)?,
        receipt_object_sha256: row.get(11)?,
        frame_key_sha256s,
        materialization_status: row.get(13)?,
        canonical_sha256: row.get(14)?,
        created_at: row.get(15)?,
    })
}

fn same_fictional_energy_vfx_sequence_link(
    left: &FictionalEnergyVfxSequenceLinkRecord,
    right: &FictionalEnergyVfxSequenceLinkRecord,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left == right
}

fn fictional_energy_vfx_sequence_reachable_hashes(
    link: &FictionalEnergyVfxSequenceLinkRecord,
) -> Vec<String> {
    vec![link.receipt_object_sha256.clone()]
}

fn validate_fictional_energy_vfx_sequence_binding_in_transaction(
    connection: &Connection,
    link: &FictionalEnergyVfxSequenceLinkRecord,
) -> Result<(), StoreError> {
    let delivery: Option<(String, String, String)> = connection
        .query_row(
            "SELECT project_id, lod0_candidate_id, lod0_artifact_sha256 FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1",
            params![link.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if delivery.as_ref().map(|value| value.0.as_str()) != Some(link.project_id.as_str())
        || delivery.as_ref().map(|value| value.1.as_str())
            != Some(link.source_candidate_id.as_str())
        || delivery.as_ref().map(|value| value.2.as_str())
            != Some(link.source_artifact_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_SEQUENCE_DELIVERY_BINDING_MISMATCH".to_owned(),
            message: "sequence project/candidate/artifact differs from durable LOD0".to_owned(),
        });
    }
    let profile: Option<(String, String)> = connection
        .query_row(
            "SELECT project_id, vfx_profile_object_sha256 FROM fictional_energy_vfx_links WHERE delivery_manifest_object_sha256 = ?1",
            params![link.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    if profile.as_ref().map(|value| value.0.as_str()) != Some(link.project_id.as_str())
        || profile.as_ref().map(|value| value.1.as_str())
            != Some(link.vfx_profile_object_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_SEQUENCE_PROFILE_BINDING_MISMATCH".to_owned(),
            message: "sequence project/profile differs from the durable VFX profile".to_owned(),
        });
    }
    Ok(())
}

fn ensure_fictional_energy_vfx_sequence_object(
    connection: &Connection,
    link: &FictionalEnergyVfxSequenceLinkRecord,
) -> Result<(), StoreError> {
    ensure_fictional_energy_vfx_frame_object(
        connection,
        &link.receipt_object_sha256,
        "application/json",
        FICTIONAL_ENERGY_VFX_SEQUENCE_RECEIPT_KIND,
        i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
    )
}

fn validate_appearance_source_lineage_link(
    link: &AppearanceSourceLineageLinkRecord,
) -> Result<(), StoreError> {
    let mut canonical = link.clone();
    canonical.canonical_sha256.clear();
    let expected = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    if link.schema_version != "AppearanceSourceLineageLink@1"
        || !is_opaque_id(&link.project_id)
        || !is_opaque_id(&link.candidate_id)
        || !is_sha256(&link.candidate_state_sha256)
        || !is_sha256(&link.source_replay_worker_cohort_sha256)
        || !matches!(
            link.appearance_program_schema_version.as_str(),
            "AppearanceProgram@2" | "AppearanceProgram@3"
        )
        || !is_sha256(&link.appearance_program_object_sha256)
        || !is_sha256(&link.appearance_program_sha256)
        || !is_sha256(&link.geometry_program_object_sha256)
        || !is_sha256(&link.geometry_program_sha256)
        || link
            .material_layer_stack_sha256
            .as_ref()
            .is_some_and(|value| !is_sha256(value))
        || !is_opaque_id(&link.material_pack_id)
        || link.material_pack_version.is_empty()
        || link.material_pack_version.len() > 64
        || link.material_pack_license_spdx.is_empty()
        || link.material_pack_license_spdx.len() > 128
        || !is_sha256(&link.material_pack_provenance_sha256)
        || !is_sha256(&link.material_pack_manifest_object_sha256)
        || !is_sha256(&link.material_pack_manifest_sha256)
        || !is_sha256(&link.texture_build_receipt_object_sha256)
        || !is_sha256(&link.texture_build_receipt_sha256)
        || link
            .candidate_surface_bake_receipt_object_sha256
            .as_ref()
            .is_some_and(|value| !is_sha256(value))
        || link
            .candidate_surface_bake_receipt_sha256
            .as_ref()
            .is_some_and(|value| !is_sha256(value))
        || !is_sha256(&link.uv_binding_sha256)
        || link.lod_candidate_ids.len() != 3
        || link
            .lod_candidate_ids
            .iter()
            .any(|value| !is_opaque_id(value))
        || link.lod_candidate_ids.iter().collect::<HashSet<_>>().len() != 3
        || link.lod_candidate_state_sha256s.len() != 3
        || link
            .lod_candidate_state_sha256s
            .iter()
            .any(|value| !is_sha256(value))
        || link.lod_artifact_sha256s.len() != 3
        || link
            .lod_artifact_sha256s
            .iter()
            .any(|value| !is_sha256(value))
        || link
            .lod_artifact_sha256s
            .iter()
            .collect::<HashSet<_>>()
            .len()
            != 3
        || link.lod_artifact_readback_sha256s.len() != 3
        || link
            .lod_artifact_readback_sha256s
            .iter()
            .any(|value| !is_sha256(value))
        || link.lod_artifact_readback_object_sha256s.len() != 3
        || link
            .lod_artifact_readback_object_sha256s
            .iter()
            .any(|value| !is_sha256(value))
        || link.lod_part_binding_inventory_sha256s.len() != 3
        || link
            .lod_part_binding_inventory_sha256s
            .iter()
            .any(|value| !is_sha256(value))
        || link.request_sha256.len() != 64
        || !is_sha256(&link.request_sha256)
        || !is_sha256(&link.sidecar_object_sha256)
        || link.materialization_status != "runtime-owned-durable-appearance-source-lineage"
        || link.canonical_sha256 != expected
        || link.created_at.is_empty()
        || link.created_at.len() > 128
    {
        return Err(StoreError::InvalidData(
            "Appearance source lineage link is malformed".to_owned(),
        ));
    }
    if link.lod_candidate_ids[0] != link.candidate_id
        || link.lod_candidate_state_sha256s[0] != link.candidate_state_sha256
    {
        return Err(StoreError::InvalidData(
            "Appearance source lineage LOD0 does not bind the source candidate".to_owned(),
        ));
    }
    Ok(())
}

