        let sql = format!(
            "SELECT {column} FROM fictional_energy_vfx_animated_socket_trails_bloom_v2_projection_sequence_links WHERE sequence_key_sha256 = ?1"
        );
        let stored: i64 = connection.query_row(&sql, params![key], |row| row.get(0))?;
        if value.get(field).and_then(Value::as_u64) != u64::try_from(stored).ok() {
            return Err(mismatch(field));
        }
