    fn authoring_commit_records(
        candidate: &CandidateRecord,
        evidence: &GeometryCandidateEvidenceRecord,
        source_candidate_id: &str,
        request_sha256: &str,
    ) -> (JobRecord, JobEventRecord, AuditEventRecord, String) {
        let job_id = format!("job-{}", candidate.candidate_id);
        let job = JobRecord {
            schema_version: "RuntimeJob@1".to_owned(),
            job_id: job_id.clone(),
            project_id: candidate.project_id.clone(),
            kind: AUTHORING_MESH_EDIT_PREPARE_TOOL.to_owned(),
            status: "succeeded".to_owned(),
            progress: 100,
            request_sha256: request_sha256.to_owned(),
            checkpoint_sha256: None,
            error_code: None,
            created_at: "1".to_owned(),
            updated_at: "1".to_owned(),
        };
        let event = JobEventRecord {
            schema_version: "RuntimeJobEvent@1".to_owned(),
            job_id: job_id.clone(),
            sequence: 1,
            kind: "authoring_mesh_edit_prepared".to_owned(),
            payload: serde_json::json!({
                "candidate_id": candidate.candidate_id,
                "source_candidate_id": source_candidate_id,
                "geometry_candidate_evidence_sha256": evidence.canonical_sha256,
            }),
            created_at: "1".to_owned(),
        };
        let audit = AuditEventRecord {
            schema_version: "AuditEvent@1".to_owned(),
            audit_id: format!("audit-{}", candidate.candidate_id),
            project_id: Some(candidate.project_id.clone()),
            kind: AUTHORING_MESH_EDIT_PREPARE_TOOL.to_owned(),
            object_id: Some(candidate.candidate_id.clone()),
            request_sha256: Some(request_sha256.to_owned()),
            payload: serde_json::json!({
                "candidate_id": candidate.candidate_id,
                "source_candidate_id": source_candidate_id,
                "geometry_candidate_evidence_sha256": evidence.canonical_sha256,
            }),
            created_at: "1".to_owned(),
        };
        let response = serde_json::to_string(&serde_json::json!({
            "schema_version": "AuthoringMeshEditPrepare@1",
            "candidate_id": candidate.candidate_id,
            "project_id": candidate.project_id,
            "source_candidate_id": source_candidate_id,
            "geometry_candidate_evidence_sha256": evidence.canonical_sha256,
            "version_created": false,
            "confirmed": false,
        }))
        .expect("authoring response");
        (job, event, audit, response)
    }

    fn table_count(store: &Store, table: &str) -> i64 {
        let connection = store.lock_connection().expect("lock");
        connection
            .query_row(&format!("SELECT COUNT(*) FROM {table}"), [], |row| {
                row.get(0)
            })
            .expect("table count")
    }

