    #[test]
    fn game_weapon_animated_glb_socket_transform_projection_roundtrips_and_marks_reachable() {
        let (store, projection, projection_object, reachable) = transform_projection_fixture();
        let recorded = store
            .record_game_weapon_animated_glb_socket_transform_projection(
                &projection,
                &projection_object.record,
            )
            .expect("record transform projection");
        assert_eq!(recorded, projection);
        assert_eq!(
            table_count(
                &store,
                "game_weapon_animated_glb_socket_transform_projection_links",
            ),
            1
        );
        assert_eq!(
            table_count(
                &store,
                "game_weapon_animated_glb_socket_transform_projection_frames",
            ),
            1
        );
        assert_eq!(
            store
                .get_game_weapon_animated_glb_socket_transform_projection(
                    &projection.projection_key_sha256,
                )
                .expect("get transform projection")
                .expect("transform projection"),
            projection
        );
        assert_eq!(
            store
                .get_game_weapon_animated_glb_socket_transform_projection_object_sha256(
                    &projection.projection_key_sha256,
                )
                .expect("get projection object hash")
                .as_deref(),
            Some(projection_object.record.sha256.as_str())
        );
        let connection = store.lock_connection().expect("lock");
        for hash in reachable {
            assert_eq!(
                connection
                    .query_row(
                        "SELECT reachability FROM objects WHERE sha256 = ?1",
                        params![hash],
                        |row| row.get::<_, String>(0),
                    )
                    .expect("reachable projection dependency"),
                "reachable"
            );
        }
        drop(connection);
        assert!(store
            .get_object(&projection.projection_key_sha256)
            .expect("projection key is not a CAS object")
            .is_none());
    }

    #[test]
    fn game_weapon_animated_glb_socket_transform_projection_is_idempotent_and_conflict_fail_closed()
    {
        let (store, projection, projection_object, _) = transform_projection_fixture();
        store
            .record_game_weapon_animated_glb_socket_transform_projection(
                &projection,
                &projection_object.record,
            )
            .expect("record transform projection");
        assert_eq!(
            store
                .record_game_weapon_animated_glb_socket_transform_projection(
                    &projection,
                    &projection_object.record,
                )
                .expect("idempotent transform projection"),
            projection
        );

        let mut conflict = projection.clone();
        conflict.input_sha256 = transform_projection_hash(99);
        conflict.canonical_sha256 = transform_projection_canonical(&conflict);
        let conflict_bytes = canonical_json_bytes(
            &serde_json::to_value(&conflict).expect("conflict projection JSON"),
        )
        .expect("conflict projection bytes");
        let conflict_object = store
            .put_object(
                &conflict_bytes,
                None,
                GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_MIME,
                GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_KIND,
                "2",
            )
            .expect("conflict projection object");
        assert!(matches!(
            store.record_game_weapon_animated_glb_socket_transform_projection(
                &conflict,
                &conflict_object.record,
            ),
            Err(StoreError::Contract { code, .. })
                if code == "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_CONFLICT"
        ));
        assert_eq!(
            table_count(
                &store,
                "game_weapon_animated_glb_socket_transform_projection_links",
            ),
            1
        );
        assert_eq!(
            table_count(
                &store,
                "game_weapon_animated_glb_socket_transform_projection_frames",
            ),
            1
        );
    }

