    #[test]
    fn production_stage_transition_pass_advances_head_and_replays_exactly() {
        let (store, transition, receipt) = production_stage_store_fixture(true, "passed");
        let (recorded, replayed) = store
            .record_production_stage_transition_with_replay(&transition, &receipt.record)
            .expect("record transition");
        assert!(!replayed);
        assert_eq!(recorded, transition);
        assert_eq!(
            store
                .get_production_stage_head(
                    &transition.session_id,
                    &transition.project_id,
                    &transition.candidate_id,
                )
                .expect("production head"),
            "gray-model"
        );
        let (_, replayed) = store
            .record_production_stage_transition_with_replay(&transition, &receipt.record)
            .expect("replay transition");
        assert!(replayed);
        assert_eq!(
            store
                .get_production_stage_transition(&transition.transition_id)
                .expect("read transition"),
            Some(transition.clone())
        );
        assert_eq!(
            store
                .get_object(&receipt.record.sha256)
                .expect("receipt metadata")
                .expect("receipt")
                .reachability,
            "reachable"
        );
    }

    #[test]
    fn production_stage_transition_blocked_keeps_draft_head() {
        let (store, transition, receipt) = production_stage_store_fixture(false, "blocked");
        store
            .record_production_stage_transition(&transition, &receipt.record)
            .expect("record blocked transition");
        assert_eq!(
            store
                .get_production_stage_head(
                    &transition.session_id,
                    &transition.project_id,
                    &transition.candidate_id,
                )
                .expect("production head"),
            "draft"
        );
        let mut forged_pass = transition.clone();
        forged_pass.transition_id = "transition-forged-pass".to_owned();
        forged_pass.gate_status = "pass".to_owned();
        forged_pass.status = "passed".to_owned();
        forged_pass.canonical_sha256.clear();
        forged_pass.canonical_sha256 = canonical_json_hash(
            &serde_json::to_value(&forged_pass).expect("forged canonical value"),
        );
        let forged_payload =
            production_stage_transition_payload_json(&forged_pass).expect("forged payload");
        let forged_receipt = store
            .put_object(
                forged_payload.as_bytes(),
                None,
                "application/json",
                PRODUCTION_STAGE_TRANSITION_KIND,
                "1",
            )
            .expect("forged receipt");
        assert!(matches!(
            store.record_production_stage_transition(&forged_pass, &forged_receipt.record),
            Err(StoreError::Contract { code, .. })
                if code == "PRODUCTION_STAGE_STRUCTURAL_GATE_FAILED"
        ));
    }

    #[test]
    fn production_stage_transition_rejects_skip_canonical_drift_and_closed_kind() {
        let (store, transition, receipt) = production_stage_store_fixture(true, "passed");
        let mut skipped = transition.clone();
        skipped.to_stage = "topology".to_owned();
        skipped.canonical_sha256.clear();
        skipped.canonical_sha256 =
            canonical_json_hash(&serde_json::to_value(&skipped).expect("skip canonical value"));
        assert!(matches!(
            store.record_production_stage_transition(&skipped, &receipt.record),
            Err(StoreError::Contract { code, .. })
                if code == "PRODUCTION_STAGE_TRANSITION_NOT_ADJACENT"
        ));
        let mut corrupt = transition;
        corrupt.canonical_sha256 = "9".repeat(64);
        assert!(matches!(
            store.record_production_stage_transition(&corrupt, &receipt.record),
            Err(StoreError::Contract { code, .. })
                if code == "PRODUCTION_STAGE_TRANSITION_CANONICAL_MISMATCH"
        ));
        assert!(temporary_reserved_object_metadata_is_allowed(
            "application/json",
            PRODUCTION_STAGE_TRANSITION_KIND,
            1,
        ));
        assert!(!temporary_reserved_object_metadata_is_allowed(
            "application/octet-stream",
            PRODUCTION_STAGE_TRANSITION_KIND,
            1,
        ));
        assert!(!temporary_reserved_object_metadata_is_allowed(
            "application/json",
            "agentic-production-stage-transition-unknown",
            1,
        ));
    }

