    #[test]
    fn game_weapon_animated_glb_socket_materialization_v2_store_roundtrips_and_reaches_ancestors() {
        let (store, link, expected_hashes) =
            game_weapon_animated_glb_socket_materialization_v2_store_fixture();
        let recorded = store
            .record_game_weapon_animated_glb_socket_materialization_v2_link(&link)
            .expect("record V2 animated socket");
        assert_eq!(recorded, link);
        assert_eq!(
            table_count(
                &store,
                "game_weapon_animated_glb_socket_materialization_v2_links",
            ),
            1
        );
        assert_eq!(
            store
                .get_game_weapon_animated_glb_socket_materialization_v2_link(
                    &link.animated_socket_materialization_key_sha256,
                )
                .expect("get V2 animated socket")
                .expect("V2 animated socket"),
            link
        );
        for hash in expected_hashes {
            assert_eq!(
                store
                    .get_object(&hash)
                    .expect("V2 ancestor metadata")
                    .expect("V2 ancestor object")
                    .reachability,
                "reachable",
                "V2 ancestor {hash} must remain reachable",
            );
        }
        assert!(store
            .get_object(&link.animated_socket_materialization_key_sha256)
            .expect("V2 child key lookup")
            .is_none());
        assert!(store
            .get_object(&link.animation_glb_key_sha256)
            .expect("V2 parent key lookup")
            .is_none());
    }

