    #[test]
    fn game_weapon_animated_glb_socket_transform_projection_v2_is_idempotent_and_conflict_closed() {
        let (store, projection, object) = transform_projection_v2_fixture();
        store
            .record_game_weapon_animated_glb_socket_transform_projection_v2(
                &projection,
                &object.record,
            )
            .expect("record V2 projection");
        assert_eq!(
            store
                .record_game_weapon_animated_glb_socket_transform_projection_v2(
                    &projection,
                    &object.record,
                )
                .expect("replay V2 projection"),
            projection
        );
        let mut conflict = projection.clone();
        conflict.frames[0].source_animation_sample_sha256 = "f".repeat(64);
        conflict.frames[0].canonical_sha256.clear();
        conflict.frames[0].canonical_sha256 = canonical_json_hash(
            &serde_json::to_value(&conflict.frames[0]).expect("V2 conflict frame canonical value"),
        );
        conflict.canonical_sha256.clear();
        conflict.canonical_sha256 = canonical_json_hash(
            &serde_json::to_value(&conflict).expect("V2 conflict canonical value"),
        );
        let conflict_object = put_transform_projection_v2_object(&store, &conflict);
        assert!(matches!(
            store.record_game_weapon_animated_glb_socket_transform_projection_v2(
                &conflict,
                &conflict_object.record,
            ),
            Err(StoreError::Contract { code, .. })
                if code == "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_LINK_CONFLICT"
        ));
    }

