    #[test]
    fn game_weapon_animated_glb_socket_transform_projection_v2_preserves_non_unit_translation_composition(
    ) {
        let parent = forgecad_contracts::GameWeaponAnimatedGlbSocketTransformProjectionV2Pose {
            translation_m: vec![0.0, 0.0, 0.0],
            rotation_quat_xyzw: vec![0.0, 0.0, 0.0, 1.0],
            scale_xyz: vec![1.0, 1.0, 1.0],
        };
        let local = forgecad_contracts::GameWeaponAnimatedGlbSocketTransformProjectionV2Pose {
            translation_m: vec![0.2, 0.3, 0.4],
            rotation_quat_xyzw: vec![0.0, 0.0, 0.0, 1.0],
            scale_xyz: vec![1.0, 1.0, 1.0],
        };
        let (translation, rotation) = projection_v2_compose_poses(&parent, &local);
        assert!(projection_v2_approx_equal(translation[0] as f64, 0.2));
        assert!(projection_v2_approx_equal(translation[1] as f64, 0.3));
        assert!(projection_v2_approx_equal(translation[2] as f64, 0.4));
        assert_eq!(rotation, [0.0, 0.0, 0.0, 1.0]);
    }

