    fn candidate_material_surface_quality_store_allowlist_and_gc_roots_are_closed() {
        assert!(temporary_reserved_object_metadata_is_allowed(
            "application/json",
            CANDIDATE_MATERIAL_SURFACE_QUALITY_REPORT_KIND,
            1,
        ));
        assert!(!temporary_reserved_object_metadata_is_allowed(
            "application/json",
            "candidate-material-surface-quality-report-unknown",
            1,
        ));
        let (store, quality, report) = candidate_material_surface_quality_store_fixture();
        store
            .record_candidate_material_surface_quality(&quality, &report.record)
            .expect("record material-surface quality");
        let mut connection = store.lock_connection().expect("lock");
        let transaction = connection.transaction().expect("transaction");
        for hash in [
            report.record.sha256.as_str(),
            quality.source_artifact_sha256.as_str(),
            quality.output_artifact_sha256.as_str(),
            quality
                .appearance_source_lineage_sidecar_object_sha256
                .as_str(),
        ] {
            assert!(
                authoring_mesh_edit_object_is_linked(&transaction, hash).expect("linked query"),
                "expected material-surface root {hash} to remain linked"
            );
        }
        let lod1_artifact_hash: String = transaction
            .query_row(
                "SELECT lod1_artifact_sha256 FROM appearance_source_lineage_links WHERE candidate_id = ?1",
                params![quality.output_candidate_id],
                |row| row.get(0),
            )
            .expect("LOD1 lineage artifact");
        assert!(
            authoring_mesh_edit_object_is_linked(&transaction, &lod1_artifact_hash)
                .expect("LOD1 linked query"),
            "expected Appearance lineage LOD1 root to remain linked"
        );
        transaction.rollback().expect("rollback read-only check");
    }

