    #[test]
    fn candidate_animation_vfx_quality_record_enforces_twenty_hard_gates() {
        let quality = candidate_animation_vfx_quality_test_record();
        validate_candidate_animation_vfx_quality(&quality).expect("valid quality record");
        let mut blocked = quality.clone();
        blocked.hard_gate.vfx_glb_socket_attachment = false;
        blocked.validator_status = "failed".to_owned();
        blocked.hard_gate_passed = false;
        blocked.canonical_sha256.clear();
        blocked.canonical_sha256 =
            canonical_json_hash(&serde_json::to_value(&blocked).expect("blocked quality value"));
        validate_candidate_animation_vfx_quality(&blocked)
            .expect("blocked record remains auditable");
        blocked.validator_status = "passed".to_owned();
        blocked.canonical_sha256.clear();
        blocked.canonical_sha256 =
            canonical_json_hash(&serde_json::to_value(&blocked).expect("invalid quality value"));
        assert!(validate_candidate_animation_vfx_quality(&blocked).is_err());
    }

