    #[test]
    fn fictional_energy_vfx_animated_socket_particles_sequence_validates_bounded_contiguous_frames()
    {
        let one = animated_socket_particles_sequence_test_record(1);
        validate_fictional_energy_vfx_animated_socket_particles_sequence(&one)
            .expect("one-frame sequence should validate");
        let sixteen = animated_socket_particles_sequence_test_record(16);
        validate_fictional_energy_vfx_animated_socket_particles_sequence(&sixteen)
            .expect("sixteen-frame sequence should validate");

        let mut empty = one.clone();
        empty.frames.clear();
        assert!(validate_fictional_energy_vfx_animated_socket_particles_sequence(&empty).is_err());

        let mut non_contiguous = animated_socket_particles_sequence_test_record(2);
        non_contiguous.frames[1].frame_index = 2;
        assert!(
            validate_fictional_energy_vfx_animated_socket_particles_sequence(&non_contiguous)
                .is_err()
        );
    }

