    #[test]
    fn fictional_energy_vfx_animated_socket_particles_sequence_replay_normalizes_metadata_but_not_bindings(
    ) {
        let original = animated_socket_particles_sequence_test_record(2);
        let mut replay = original.clone();
        replay.created_at = "2026-08-22T00:00:00Z".to_owned();
        replay.canonical_sha256 = "f".repeat(64);
        for frame in &mut replay.frames {
            frame.created_at = "2026-08-22T00:00:00Z".to_owned();
            frame.canonical_sha256 = "e".repeat(64);
        }
        assert!(same_fictional_energy_vfx_animated_socket_particles_sequence(&original, &replay));

        replay.frames[0].particle_key_sha256 = "d".repeat(64);
        assert!(!same_fictional_energy_vfx_animated_socket_particles_sequence(&original, &replay));
    }

