    #[test]
    fn fictional_energy_vfx_animated_socket_particles_sequence_v2_api_rejects_v1_parent_key_without_rows(
    ) {
        let root = test_root("animated-particles-sequence-v2-v1-key-isolation");
        let db = root.join("runtime.sqlite3");
        let store = Store::open(&db).expect("store");
        let key = format!("{:064x}", 0xfeed_u64);
        let connection = store.lock_connection().expect("connection");
        // Seed only the legacy V1 table with an intentionally invalid but
        // structurally complete row.  The V2 getter must not fall back to it.
        connection
            .execute_batch("PRAGMA foreign_keys = OFF; PRAGMA ignore_check_constraints = ON;")
            .expect("disable isolated test constraints");
        let columns: Vec<String> = {
            let mut statement = connection
                .prepare(
                    "SELECT name FROM pragma_table_info('fictional_energy_vfx_animated_socket_particles_sequence_links') ORDER BY cid",
                )
                .expect("table info");
            statement
                .query_map([], |row| row.get(0))
                .expect("table columns")
                .collect::<Result<Vec<String>, _>>()
                .expect("column names")
        };
        let quoted_columns = columns
            .iter()
            .map(|column| format!("\"{column}\""))
            .collect::<Vec<_>>()
            .join(", ");
        let placeholders = (1..=columns.len())
            .map(|index| format!("?{index}"))
            .collect::<Vec<_>>()
            .join(", ");
        let values = columns
            .iter()
            .map(|column| {
                if column == "sequence_key_sha256" {
                    rusqlite::types::Value::Text(key.clone())
                } else {
                    rusqlite::types::Value::Text("v1-only-row".to_owned())
                }
            })
            .collect::<Vec<_>>();
        connection
            .execute(
                &format!(
                    "INSERT INTO fictional_energy_vfx_animated_socket_particles_sequence_links ({quoted_columns}) VALUES ({placeholders})"
                ),
                rusqlite::params_from_iter(values),
            )
            .expect("legacy V1 seed");
        drop(connection);

        assert_eq!(
            store
                .get_fictional_energy_vfx_animated_socket_particles_sequence_v2(&key)
                .expect("V2 getter"),
            None
        );
        assert_eq!(
            table_count(
                &store,
                "fictional_energy_vfx_animated_socket_particles_sequence_links"
            ),
            1
        );
        assert_eq!(
            table_count(
                &store,
                "fictional_energy_vfx_animated_socket_particles_v2_projection_sequence_links"
            ),
            0
        );
        fs::remove_dir_all(root).expect("cleanup");
    }

